{
  "name": "HealthShield AI - Secure Medical Record Management",
  "description": "A comprehensive AI-powered health record management system featuring August AI for medical insights, secure data storage, and unique Health ID generation for quick access to medical history."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface UserProfile {
  name: string;
  age: number;
  dob: string;
  phone: string;
  aadhaar: string;
  healthId: string;
}

export interface MedicalProblem {
  id: string;
  condition: string;
  status: 'past' | 'present';
  onsetDate: string;
}

export interface Medication {
  id: string;
  name: string;
  dosage: string;
  duration: string;
  frequency: string;
}

export interface Surgery {
  id: string;
  type: string;
  date: string;
  hospital: string;
}

export interface Allergy {
  id: string;
  substance: string;
  severity: 'low' | 'moderate' | 'high';
}

export interface TreatmentNote {
  id: string;
  doctorName: string;
  date: string;
  note: string;
}

export interface HealthRecord {
  profile: UserProfile;
  problems: MedicalProblem[];
  medications: Medication[];
  surgeries: Surgery[];
  allergies: Allergy[];
  notes: TreatmentNote[];
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import React from 'react';

export const APP_NAME = "HealthShield AI";
export const AI_NAME = "August AI";

export const ICONS = {
  HEALTH_ID: <i className="fas fa-id-card"></i>,
  MEDICAL: <i className="fas fa-notes-medical"></i>,
  MEDS: <i className="fas fa-pills"></i>,
  SURGERY: <i className="fas fa-hospital-user"></i>,
  ALLERGY: <i className="fas fa-allergies"></i>,
  NOTE: <i className="fas fa-clipboard-list"></i>,
  AI: <i className="fas fa-robot"></i>,
  LOCK: <i className="fas fa-shield-alt"></i>,
  SEARCH: <i className="fas fa-search"></i>,
  USER: <i className="fas fa-user-circle"></i>,
  DASHBOARD: <i className="fas fa-chart-line"></i>,
  ADD: <i className="fas fa-plus-circle"></i>,
  HISTORY: <i className="fas fa-history"></i>,
  LOGOUT: <i className="fas fa-sign-out-alt"></i>
};

export const STORAGE_KEY = 'health_shield_records';

import { GoogleGenAI } from "@google/genai";
import { HealthRecord } from "../types";

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are August AI, a professional medical records assistant. 
    Analyze the provided health history for this user: ${JSON.stringify(record)}.

    Guidelines:
    1. Always include a disclaimer: "I am August AI, a guidance assistant. I am not a substitute for professional medical advice, diagnosis, or treatment. Always seek the advice of your physician."
    2. Analyze past and present medical problems, medications, surgeries, and allergies.
    3. Look for potential medication conflicts or contradictions with the user's allergies.
    4. Suggest healthy lifestyle changes (diet, exercise, sleep) based on their specific health profile.
    5. Be concise, professional, and empathetic.
    6. Mask sensitive IDs if you mention them (e.g., Aadhaar).

    Current User Context:
    Name: ${record.profile.name}
    Health ID: ${record.profile.healthId}
    Aadhaar: ${record.profile.aadhaar.replace(/\d(?=\d{4})/g, "*")}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.7,
        thinkingConfig: { thinkingBudget: 5000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your health records at the moment.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data. Please try again later.";
  }
};

