};

export default RecordCard;

import React, { useState, useEffect, useCallback } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);

  // AI State
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');

  // Form states for adding records
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  // Load records from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setAllRecords(JSON.parse(saved));
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: formData.get('name') as string,
      age: parseInt(formData.get('age') as string),
      dob: formData.get('dob') as string,
      phone: formData.get('phone') as string,
      aadhaar: formData.get('aadhaar') as string,
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [],
      medications: [],
      surgeries: [],
      allergies: [],
      notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    setIsAuth(true);
  };

  const handleLogin = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const healthId = new FormData(e.currentTarget).get('healthId') as string;
    const found = allRecords.find(r => r.profile.healthId === healthId);
    if (found) {
      setCurrentUser(found);
      setIsAuth(true);
    } else {
      alert("Health ID not found. Please register.");
    }
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const updatedUser = {
      ...currentUser,
      [type]: [...(currentUser[type] as any[]), { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);

    const updatedAll = allRecords.map(r => 
      r.profile.healthId === currentUser.profile.healthId ? updatedUser : r
    );
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;

    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);

    const response = await analyzeHealthRecord(currentUser, userQuery);

    const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
    setChatHistory(prev => [...prev, aiMsg]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const found = allRecords.find(r => r.profile.healthId === searchId);
    setSearchResults(found || null);
    if (!found) alert("No records found for this Health ID.");
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="absolute bottom-0 left-0 w-32 h-32 bg-white/5 rounded-full -ml-10 -mb-10"></div>

            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">
                {ICONS.LOCK}
              </div>
              <h1 className="text-4xl font-bold mb-4">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8">Your complete digital medical memory, secured and powered by intelligence.</p>

              <ul className="space-y-4">
                <li className="flex items-center space-x-3">
                  <div className="w-6 h-6 rounded-full bg-indigo-500/50 flex items-center justify-center text-xs">✓</div>
                  <span>Secure Aadhaar Vault</span>
                </li>
                <li className="flex items-center space-x-3">
                  <div className="w-6 h-6 rounded-full bg-indigo-500/50 flex items-center justify-center text-xs">✓</div>
                  <span>Unique Health ID Generation</span>
                </li>
                <li className="flex items-center space-x-3">
                  <div className="w-6 h-6 rounded-full bg-indigo-500/50 flex items-center justify-center text-xs">✓</div>
                  <span>August AI Health Companion</span>
                </li>
              </ul>
            </div>
          </div>

          <div className="p-10">
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-slate-800">Get Started</h2>
              <p className="text-slate-500">Login or create your secure health profile</p>
            </div>

            <div className="space-y-8">
              {/* Simple Toggle between Login/Register */}
              <div className="bg-slate-100 p-1 rounded-xl flex">
                <button className="flex-1 py-2 text-sm font-semibold text-slate-800 bg-white rounded-lg shadow-sm">Registration</button>
              </div>

              <form onSubmit={handleRegister} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Full Name</label>
                    <input required name="name" type="text" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all" placeholder="John Doe" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="25" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Date of Birth</label>
                  <input required name="dob" type="date" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Phone Number</label>
                  <input required name="phone" type="tel" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="+91 98765 43210" />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Aadhaar Number</label>
                  <input required name="aadhaar" type="text" pattern="\d{12}" title="12 digit Aadhaar" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="1234 5678 9012" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-indigo-200 transition-all">
                  Register Securely
                </button>
              </form>

              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-slate-100"></div>
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-white px-2 text-slate-400 font-bold">Or Login with ID</span>
                </div>
              </div>

              <form onSubmit={handleLogin} className="flex space-x-2">
                <input name="healthId" type="text" className="flex-grow px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="HID-XXXX-XXXX" />
                <button type="submit" className="bg-slate-800 text-white px-6 rounded-xl font-bold hover:bg-black transition-all">Login</button>
              </form>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const renderDashboard = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32"></div>
          <div className="relative z-10 flex flex-col h-full justify-between">
            <div>
              <p className="text-indigo-100 font-medium mb-1">Personal Health Passport</p>
              <h1 className="text-3xl font-bold mb-6">Unique Health ID</h1>
              <div className="flex items-center space-x-4 mb-8">
                <div className="bg-white/20 backdrop-blur-md px-6 py-4 rounded-2xl border border-white/20">
                  <span className="text-2xl font-mono font-bold tracking-[0.2em]">{currentUser?.profile.healthId}</span>
                </div>
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(currentUser?.profile.healthId || '');
                    alert("ID Copied!");
                  }}
                  className="w-12 h-12 rounded-xl bg-white/10 hover:bg-white/20 flex items-center justify-center transition-all"
                >
                  <i className="far fa-copy text-xl"></i>
                </button>
              </div>
            </div>
            <div className="flex items-center justify-between border-t border-white/10 pt-6">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 rounded-full border-2 border-white/30 p-1">
                  <img src={`https://picsum.photos/seed/${currentUser?.profile.name}/100/100`} className="rounded-full" />
                </div>
                <div>
                  <p className="text-sm font-bold">{currentUser?.profile.name}</p>
                  <p className="text-xs text-indigo-100">{currentUser?.profile.age} Yrs • {currentUser?.profile.dob}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="text-[10px] uppercase font-bold text-indigo-200">Phone Verified</p>
                <p className="text-xs font-mono">{currentUser?.profile.phone}</p>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100 flex flex-col justify-center">
          <h3 className="text-slate-500 font-bold text-sm uppercase mb-4">Quick Stats</h3>
          <div className="space-y-4">
            <div className="flex items-center justify-between p-3 rounded-2xl bg-rose-50 border border-rose-100">
              <div className="flex items-center space-x-3">
                <span className="text-rose-500">{ICONS.ALLERGY}</span>
                <span className="font-semibold text-rose-900">Allergies</span>
              </div>
              <span className="font-bold text-rose-700">{currentUser?.allergies.length}</span>
            </div>
            <div className="flex items-center justify-between p-3 rounded-2xl bg-blue-50 border border-blue-100">
              <div className="flex items-center space-x-3">
                <span className="text-blue-500">{ICONS.MEDS}</span>
                <span className="font-semibold text-blue-900">Active Meds</span>
              </div>
              <span className="font-bold text-blue-700">{currentUser?.medications.length}</span>
            </div>
            <div className="flex items-center justify-between p-3 rounded-2xl bg-amber-50 border border-amber-100">
              <div className="flex items-center space-x-3">
                <span className="text-amber-500">{ICONS.MEDICAL}</span>
                <span className="font-semibold text-amber-900">Conditions</span>
              </div>
              <span className="font-bold text-amber-700">{currentUser?.problems.filter(p => p.status === 'present').length}</span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <RecordCard title="Current Medications" icon={ICONS.MEDS}>
          {currentUser?.medications.length === 0 ? (
            <p className="text-slate-400 text-center py-4 italic text-sm">No medications listed</p>
          ) : (
            <div className="space-y-3">
              {currentUser?.medications.map(med => (
                <div key={med.id} className="flex items-start space-x-3 p-3 rounded-xl border border-slate-100 hover:bg-slate-50 transition-all">
                  <div className="w-8 h-8 rounded-lg bg-indigo-50 flex items-center justify-center text-indigo-500">
                    {ICONS.MEDS}
                  </div>
                  <div className="flex-grow">
                    <p className="font-bold text-slate-800">{med.name}</p>
                    <p className="text-xs text-slate-500">{med.dosage} • {med.frequency}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">{med.duration}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </RecordCard>

        <RecordCard title="Allergies" icon={ICONS.ALLERGY}>
          {currentUser?.allergies.length === 0 ? (
            <p className="text-slate-400 text-center py-4 italic text-sm">No allergies reported</p>
          ) : (
            <div className="flex flex-wrap gap-2">
              {currentUser?.allergies.map(all => (
                <div key={all.id} className={`px-4 py-2 rounded-full font-bold text-xs border ${
                  all.severity === 'high' ? 'bg-red-50 text-red-700 border-red-200' : 
                  all.severity === 'moderate' ? 'bg-amber-50 text-amber-700 border-amber-200' : 
                  'bg-emerald-50 text-emerald-700 border-emerald-200'
                }`}>
                  {all.substance} ({all.severity.toUpperCase()})
                </div>
              ))}
            </div>
          )}
        </RecordCard>
      </div>
    </div>
  );

  const renderRecords = () => (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 pb-20">
      <RecordCard title="Medical Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
        <div className="space-y-3">
          {currentUser?.problems.map(p => (
            <div key={p.id} className="flex items-center justify-between p-3 rounded-xl border border-slate-100">
              <div>
                <p className="font-bold text-slate-800">{p.condition}</p>
                <p className="text-xs text-slate-500">Onset: {p.onsetDate}</p>
              </div>
              <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${p.status === 'present' ? 'bg-rose-50 text-rose-600 border border-rose-100' : 'bg-slate-100 text-slate-500'}`}>
                {p.status}
              </span>
            </div>
          ))}
        </div>
      </RecordCard>

      <RecordCard title="Surgeries & Procedures" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
        <div className="space-y-3">
          {currentUser?.surgeries.map(s => (
            <div key={s.id} className="p-3 rounded-xl border border-slate-100">
              <div className="flex justify-between items-start mb-1">
                <p className="font-bold text-slate-800">{s.type}</p>
                <p className="text-xs font-medium text-slate-400">{s.date}</p>
              </div>
              <p className="text-xs text-indigo-600 font-semibold">{s.hospital}</p>
            </div>
          ))}
        </div>
      </RecordCard>

      <RecordCard title="Doctor Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {currentUser?.notes.map(n => (
            <div key={n.id} className="p-4 rounded-2xl bg-slate-50 border border-slate-100 relative group">
              <div className="flex items-center space-x-3 mb-3">
                <div className="w-8 h-8 rounded-full bg-white shadow-sm flex items-center justify-center text-xs">Dr</div>
                <div>
                  <p className="text-xs font-bold text-slate-800">{n.doctorName}</p>
                  <p className="text-[10px] text-slate-400 font-medium">{n.date}</p>
                </div>
              </div>
              <p className="text-sm text-slate-600 italic">"{n.note}"</p>
            </div>
          ))}
        </div>
      </RecordCard>

      {/* Dynamic Modal Renderer */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowAddModal(null)}></div>
          <div className="relative w-full max-w-md bg-white rounded-3xl shadow-2xl p-8 overflow-hidden animate-in fade-in zoom-in duration-200">
            <h3 className="text-xl font-bold mb-6 text-slate-800">Add New Record</h3>

            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate') });
              if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doctor'), date: f.get('date'), note: f.get('note') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <select name="status" className="w-full px-4 py-3 rounded-xl border border-slate-200">
                    <option value="present">Present</option>
                    <option value="past">Past</option>
                  </select>
                  <input required type="date" name="onsetDate" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                </>
              )}
              {showAddModal === 'med' && (
                <>
                  <input required name="name" placeholder="Medicine Name" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <input required name="dosage" placeholder="Dosage (e.g. 500mg)" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="duration" placeholder="Duration (7 days)" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                    <input required name="frequency" placeholder="Frequency (1-0-1)" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  </div>
                </>
              )}
              {showAddModal === 'surgery' && (
                <>
                  <input required name="type" placeholder="Procedure Type" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <input required type="date" name="date" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <input required name="hospital" placeholder="Hospital Name" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Substance/Drug" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <select name="severity" className="w-full px-4 py-3 rounded-xl border border-slate-200">
                    <option value="low">Low</option>
                    <option value="moderate">Moderate</option>
                    <option value="high">High</option>
                  </select>
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <input required name="doctor" placeholder="Doctor's Name" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <input required type="date" name="date" className="w-full px-4 py-3 rounded-xl border border-slate-200" />
                  <textarea required name="note" placeholder="Doctor's Observation/Treatment Plan" className="w-full px-4 py-3 rounded-xl border border-slate-200 min-h-[100px]"></textarea>
                </>
              )}
              <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl">Add to Health Wallet</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );

  const renderAugustAI = () => (
    <div className="flex flex-col h-[calc(100vh-12rem)]">
      <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
        <div className="bg-indigo-50 border border-indigo-100 rounded-2xl p-4 flex items-start space-x-3">
          <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white flex-shrink-0">
            {ICONS.AI}
          </div>
          <div>
            <p className="font-bold text-indigo-900 mb-1">{AI_NAME}</p>
            <p className="text-sm text-indigo-800">
              Hello! I have analyzed your medical profile. I can help with medicine interactions, lifestyle suggestions, or answering questions about your history.
            </p>
            <p className="text-[10px] mt-2 font-bold uppercase text-indigo-400 italic">Medical Disclaimer: I am an AI guidance tool, not a doctor.</p>
          </div>
        </div>

        {chatHistory.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white border border-slate-200 text-slate-800 shadow-sm'}`}>
              <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
              <p className={`text-[10px] mt-2 opacity-60 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isAiLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-slate-200 rounded-2xl p-4 flex items-center space-x-2">
              <div className="flex space-x-1">
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-150"></div>
              </div>
              <span className="text-xs text-slate-400 font-medium">August is thinking...</span>
            </div>
          </div>
        )}
      </div>

      <div className="relative mt-auto">
        <div className="bg-white rounded-2xl border border-slate-200 p-2 shadow-lg flex items-center space-x-2">
          <input 
            value={userQuery}
            onChange={(e) => setUserQuery(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && askAugustAI()}
            placeholder="Ask about your medicine conflicts, diet, or history..."
            className="flex-grow px-4 py-3 outline-none text-sm bg-transparent"
          />
          <button 
            onClick={askAugustAI}
            disabled={isAiLoading || !userQuery.trim()}
            className="w-12 h-12 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl flex items-center justify-center transition-all disabled:opacity-50"
          >
            <i className="fas fa-paper-plane"></i>
          </button>
        </div>
      </div>
    </div>
  );

  const renderHistorySearch = () => (
    <div className="space-y-6">
      <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
        <h3 className="text-xl font-bold mb-4 text-slate-800">Search Universal Health Database</h3>
        <p className="text-slate-500 text-sm mb-6">Enter a unique Health ID to retrieve patient history (Restricted Access)</p>
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-grow relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">{ICONS.SEARCH}</span>
            <input 
              value={searchId}
              onChange={(e) => setSearchId(e.target.value)}
              placeholder="HID-XXXX-XXXX" 
              className="w-full pl-12 pr-4 py-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" 
            />
          </div>
          <button 
            onClick={handleSearch}
            className="bg-slate-800 text-white px-8 py-4 rounded-2xl font-bold hover:bg-black transition-all"
          >
            Fetch Records
          </button>
        </div>
      </div>

      {searchResults && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-white rounded-3xl overflow-hidden border border-slate-100 shadow-xl mb-6">
            <div className="bg-slate-800 text-white p-6 flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 rounded-full bg-slate-700 flex items-center justify-center text-xl">
                  {ICONS.USER}
                </div>
                <div>
                  <h4 className="text-xl font-bold">{searchResults.profile.name}</h4>
                  <p className="text-xs text-slate-400 uppercase font-bold tracking-widest">{searchResults.profile.healthId}</p>
                </div>
              </div>
              <div className="text-right">
                <div className="px-3 py-1 bg-emerald-500/20 text-emerald-400 rounded-full text-[10px] font-bold inline-block mb-1">DATA ENCRYPTED</div>
                <p className="text-xs text-slate-400">Verified Health Profile</p>
              </div>
            </div>

            <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <div>
                  <h5 className="text-slate-400 font-bold text-[10px] uppercase mb-3 flex items-center">
                    <span className="mr-2 text-indigo-600">{ICONS.MEDICAL}</span> Past & Present Conditions
                  </h5>
                  <div className="space-y-2">
                    {searchResults.problems.map(p => (
                      <div key={p.id} className="p-3 bg-slate-50 rounded-xl flex justify-between">
                        <span className="font-bold text-slate-700">{p.condition}</span>
                        <span className={`text-[10px] font-bold ${p.status === 'present' ? 'text-rose-600' : 'text-slate-400'}`}>{p.status.toUpperCase()}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div>
                  <h5 className="text-slate-400 font-bold text-[10px] uppercase mb-3 flex items-center">
                    <span className="mr-2 text-indigo-600">{ICONS.MEDS}</span> Active Medications
                  </h5>
                  <div className="space-y-2">
                    {searchResults.medications.map(m => (
                      <div key={m.id} className="p-3 bg-slate-50 rounded-xl flex justify-between">
                        <span className="font-bold text-slate-700">{m.name}</span>
                        <span className="text-xs text-slate-500">{m.dosage}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <div>
                  <h5 className="text-slate-400 font-bold text-[10px] uppercase mb-3 flex items-center">
                    <span className="mr-2 text-indigo-600">{ICONS.ALLERGY}</span> Allergies
                  </h5>
                  <div className="flex flex-wrap gap-2">
                    {searchResults.allergies.map(a => (
                      <span key={a.id} className="px-3 py-1 bg-rose-50 text-rose-600 border border-rose-100 rounded-full text-xs font-bold">{a.substance}</span>
                    ))}
                  </div>
                </div>

                <div>
                  <h5 className="text-slate-400 font-bold text-[10px] uppercase mb-3 flex items-center">
                    <span className="mr-2 text-indigo-600">{ICONS.NOTE}</span> Latest Doctor's Note
                  </h5>
                  {searchResults.notes.length > 0 ? (
                    <div className="p-4 bg-indigo-50/30 border border-indigo-100 rounded-2xl italic text-sm text-slate-600">
                      "{searchResults.notes[searchResults.notes.length-1].note}"
                    </div>
                  ) : (
                    <p className="text-xs text-slate-400">No clinical notes available.</p>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      userName={currentUser?.profile.name || ''}
      onLogout={() => { setIsAuth(false); setCurrentUser(null); }}
    >
      {activeTab === 'dashboard' && renderDashboard()}
      {activeTab === 'records' && renderRecords()}
      {activeTab === 'august' && renderAugustAI()}
      {activeTab === 'history' && renderHistorySearch()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');

  // Search and Login inputs
  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  // AI State
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');

  // Form states for adding records
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  // Load records and session on mount
  useEffect(() => {
    const savedRecords = localStorage.getItem(STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);

    let loadedRecords: HealthRecord[] = [];
    if (savedRecords) {
      loadedRecords = JSON.parse(savedRecords);
      setAllRecords(loadedRecords);
    }

    if (activeSession && loadedRecords.length > 0) {
      const found = loadedRecords.find(r => r.profile.healthId === activeSession);
      if (found) {
        setCurrentUser(found);
        setIsAuth(true);
      }
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: formData.get('name') as string,
      age: parseInt(formData.get('age') as string),
      dob: formData.get('dob') as string,
      phone: formData.get('phone') as string,
      aadhaar: formData.get('aadhaar') as string,
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [],
      medications: [],
      surgeries: [],
      allergies: [],
      notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsAuth(true);
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');

    if (!loginId.trim()) {
      setAuthError('Please enter your Health ID');
      return;
    }

    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === loginId.trim().toUpperCase());
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Ensure it is formatted correctly (e.g., HID-XXXX-XXXX)");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const updatedUser = {
      ...currentUser,
      [type]: [...(currentUser[type] as any[]), { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);

    const updatedAll = allRecords.map(r => 
      r.profile.healthId === currentUser.profile.healthId ? updatedUser : r
    );
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;

    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);

    const response = await analyzeHealthRecord(currentUser, userQuery);

    const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
    setChatHistory(prev => [...prev, aiMsg]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === searchId.trim().toUpperCase());
    setSearchResults(found || null);
    if (!found) alert("No records found for this Health ID.");
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="absolute bottom-0 left-0 w-32 h-32 bg-white/5 rounded-full -ml-10 -mb-10"></div>

            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">
                {ICONS.LOCK}
              </div>
              <h1 className="text-4xl font-bold mb-4">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8">Your complete digital medical memory, secured and powered by intelligence.</p>

              <ul className="space-y-4">
                <li className="flex items-center space-x-3">
                  <div className="w-6 h-6 rounded-full bg-indigo-500/50 flex items-center justify-center text-xs">✓</div>
                  <span>Secure Aadhaar Vault</span>
                </li>
                <li className="flex items-center space-x-3">
                  <div className="w-6 h-6 rounded-full bg-indigo-500/50 flex items-center justify-center text-xs">✓</div>
                  <span>Unique Health ID Generation</span>
                </li>
                <li className="flex items-center space-x-3">
                  <div className="w-6 h-6 rounded-full bg-indigo-500/50 flex items-center justify-center text-xs">✓</div>
                  <span>August AI Health Companion</span>
                </li>
              </ul>
            </div>
          </div>

          <div className="p-10 flex flex-col justify-center">
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-slate-800">{authMode === 'register' ? 'Create Secure Profile' : 'Welcome Back'}</h2>
              <p className="text-slate-500">{authMode === 'register' ? 'Register for your unique Health ID' : 'Access your records with your ID'}</p>
            </div>

            <div className="space-y-6">
              <div className="bg-slate-100 p-1 rounded-xl flex">
                <button 
                  onClick={() => { setAuthMode('register'); setAuthError(''); }}
                  className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Registration
                </button>
                <button 
                  onClick={() => { setAuthMode('login'); setAuthError(''); }}
                  className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Login
                </button>
              </div>

              {authError && (
                <div className="p-3 bg-red-50 border border-red-100 text-red-600 rounded-xl text-xs font-medium animate-in fade-in slide-in-from-top-1">
                  <i className="fas fa-exclamation-circle mr-2"></i> {authError}
                </div>
              )}

              {authMode === 'register' ? (
                <form onSubmit={handleRegister} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Full Name</label>
                      <input required name="name" type="text" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="John Doe" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Age</label>
                      <input required name="age" type="number" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="25" />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Date of Birth</label>
                    <input required name="dob" type="date" className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Phone Number</label>
