export default App;

export interface UserProfile {
  name: string;
  age: number;
  dob: string;
  phone: string;
  aadhaar: string;
  healthId: string;
  bloodGroup: string;
  emergencyContact: {
    name: string;
    phone: string;
  };
}

export interface MedicalProblem {
  id: string;
  condition: string;
  status: 'past' | 'present';
  onsetDate: string;
  severity: 'mild' | 'moderate' | 'severe';
  notes?: string;
}

export interface Medication {
  id: string;
  name: string;
  dosage: string;
  duration: string;
  frequency: string;
  prescribedBy?: string;
  sideEffects?: string;
}

export interface Surgery {
  id: string;
  type: string;
  date: string;
  hospital: string;
  surgeon?: string;
}

export interface Allergy {
  id: string;
  substance: string;
  severity: 'low' | 'moderate' | 'high';
  reaction?: string;
}

export interface TreatmentNote {
  id: string;
  doctorName: string;
  date: string;
  note: string;
  clinicName?: string;
}

export interface HealthRecord {
  profile: UserProfile;
  problems: MedicalProblem[];
  medications: Medication[];
  surgeries: Surgery[];
  allergies: Allergy[];
  notes: TreatmentNote[];
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import { GoogleGenAI } from "@google/genai";
import { HealthRecord } from "../types";

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are August AI, a professional medical records assistant. 
    Analyze the provided health history for this user: ${JSON.stringify(record)}.

    Guidelines:
    1. Always include a disclaimer: "I am August AI, a guidance assistant. I am not a substitute for professional medical advice, diagnosis, or treatment. Always seek the advice of your physician."
    2. Deeply analyze the user's Blood Group (${record.profile.bloodGroup}), Allergies, and current Medications.
    3. Look for potential drug-drug interactions or conflicts between their conditions (e.g., "Severe" hypertension vs specific medications).
    4. Provide specific lifestyle advice (diet, exercise, sleep) tailored to their Age (${record.profile.age}) and Blood Group.
    5. Mention emergency readiness: Notice if they have an emergency contact (${record.profile.emergencyContact.name}).
    6. Be professional and empathetic. Mask sensitive IDs (Aadhaar).

    Context:
    Name: ${record.profile.name}
    Health ID: ${record.profile.healthId}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 8000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your request.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data. Please try again later.";
  }
};

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  useEffect(() => {
    const savedRecords = localStorage.getItem(STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let loadedRecords: HealthRecord[] = [];
    if (savedRecords) {
      loadedRecords = JSON.parse(savedRecords);
      setAllRecords(loadedRecords);
    }
    if (activeSession && loadedRecords.length > 0) {
      const found = loadedRecords.find(r => r.profile.healthId === activeSession);
      if (found) {
        setCurrentUser(found);
        setIsAuth(true);
      }
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: formData.get('name') as string,
      age: parseInt(formData.get('age') as string),
      dob: formData.get('dob') as string,
      phone: formData.get('phone') as string,
      aadhaar: formData.get('aadhaar') as string,
      bloodGroup: formData.get('bloodGroup') as string,
      emergencyContact: {
        name: formData.get('eName') as string,
        phone: formData.get('ePhone') as string
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsAuth(true);
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === loginId.trim().toUpperCase());
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Verify your ID format.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    // STRICT DEDUPLICATION LOGIC
    const collection = currentUser[type] as any[];
    const isDuplicate = collection.some((existing: any) => {
      if (type === 'problems') return existing.condition.toLowerCase() === item.condition.toLowerCase();
      if (type === 'medications') return existing.name.toLowerCase() === item.name.toLowerCase();
      if (type === 'allergies') return existing.substance.toLowerCase() === item.substance.toLowerCase();
      if (type === 'surgeries') return existing.type.toLowerCase() === item.type.toLowerCase() && existing.date === item.date;
      return false;
    });

    if (isDuplicate) {
      alert(`This ${type.slice(0, -1)} is already in your record.`);
      return;
    }

    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);
    const updatedAll = allRecords.map(r => r.profile.healthId === currentUser.profile.healthId ? updatedUser : r);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === searchId.trim().toUpperCase());
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8">Secure digital health records with proactive AI guidance.</p>
              <div className="space-y-4">
                <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                  <p className="text-xs font-bold uppercase tracking-wider text-indigo-200 mb-2">Security Standard</p>
                  <p className="text-sm">End-to-end encryption for Aadhaar and clinical notes.</p>
                </div>
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center">
            <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-2 text-sm font-semibold rounded-lg ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-2 text-sm font-semibold rounded-lg ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
            </div>
            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold">{authError}</div>}
            {authMode === 'register' ? (
              <form onSubmit={handleRegister} className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                    <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="John Doe" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                    <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                    <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200">
                      {['A+', 'A-', 'B+', 'B-', 'O+', 'O-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                  <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="XXXX XXXX XXXX" />
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl space-y-3 border border-slate-100">
                  <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                  <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Name" />
                  <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Phone" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg">Create Health Wallet</button>
              </form>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono" placeholder="HID-XXXX-XXXX" />
                <button type="submit" className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl">Unlock Records</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} onLogout={handleLogout}>
      {activeTab === 'dashboard' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-gradient-to-r from-indigo-600 to-indigo-800 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
              <div className="relative z-10">
                <p className="text-indigo-200 text-xs font-bold uppercase mb-4 tracking-widest">Active Health Passport</p>
                <div className="flex items-end justify-between">
                  <h1 className="text-4xl font-mono font-bold tracking-tighter">{currentUser?.profile.healthId}</h1>
                  <div className="bg-white/20 px-4 py-2 rounded-xl backdrop-blur-md">
                    <p className="text-[10px] font-bold opacity-60">BLOOD GROUP</p>
                    <p className="text-xl font-bold">{currentUser?.profile.bloodGroup}</p>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                  <div>
                    <p className="text-xs text-indigo-200">Emergency Contact</p>
                    <p className="font-bold">{currentUser?.profile.emergencyContact.name} • {currentUser?.profile.emergencyContact.phone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-indigo-200">Age / DOB</p>
                    <p className="font-bold">{currentUser?.profile.age} Yrs / {currentUser?.profile.dob}</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col justify-between">
              <h3 className="text-slate-400 text-xs font-bold uppercase">Health Summary</h3>
              <div className="space-y-3 mt-4">
                <div className="flex justify-between p-3 bg-rose-50 rounded-2xl">
                  <span className="text-xs font-bold text-rose-700">Allergies</span>
                  <span className="font-black text-rose-800">{currentUser?.allergies.length}</span>
                </div>
                <div className="flex justify-between p-3 bg-blue-50 rounded-2xl">
                  <span className="text-xs font-bold text-blue-700">Active Meds</span>
                  <span className="font-black text-blue-800">{currentUser?.medications.length}</span>
                </div>
                <div className="flex justify-between p-3 bg-emerald-50 rounded-2xl">
                  <span className="text-xs font-bold text-emerald-700">Surgeries</span>
                  <span className="font-black text-emerald-800">{currentUser?.surgeries.length}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <RecordCard title="Critical Conditions" icon={ICONS.MEDICAL}>
              {currentUser?.problems.filter(p => p.status === 'present').map(p => (
                <div key={p.id} className="flex justify-between items-center p-3 border-b last:border-0">
                  <div>
                    <p className="font-bold text-slate-800">{p.condition}</p>
                    <p className="text-[10px] text-slate-400">Since {p.onsetDate}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-[10px] font-bold ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{p.severity?.toUpperCase()}</span>
                </div>
              ))}
            </RecordCard>
            <RecordCard title="Active Medications" icon={ICONS.MEDS}>
              {currentUser?.medications.map(m => (
                <div key={m.id} className="p-3 border-b last:border-0 flex justify-between">
                  <div>
                    <p className="font-bold text-slate-800">{m.name}</p>
                    <p className="text-[10px] text-slate-500">{m.dosage} • {m.frequency}</p>
                  </div>
                  <p className="text-[10px] font-bold text-indigo-600">{m.duration}</p>
                </div>
              ))}
            </RecordCard>
          </div>
        </div>
      )}
      {activeTab === 'records' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 pb-20">
          <RecordCard title="Add Condition" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
            <div className="space-y-2">
              {currentUser?.problems.map(p => (
                <div key={p.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center">
                  <span className="font-bold">{p.condition}</span>
                  <span className="text-[10px] bg-white px-2 py-1 rounded-full border">{p.status.toUpperCase()}</span>
                </div>
              ))}
            </div>
          </RecordCard>
          <RecordCard title="Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
            <div className="space-y-2">
              {currentUser?.medications.map(m => (
                <div key={m.id} className="p-3 bg-slate-50 rounded-xl flex justify-between">
                  <span className="font-bold">{m.name}</span>
                  <span className="text-xs">{m.dosage}</span>
                </div>
              ))}
            </div>
          </RecordCard>
          <RecordCard title="Doctor Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {currentUser?.notes.map(n => (
                <div key={n.id} className="p-4 bg-indigo-50/30 rounded-2xl border border-indigo-100">
                  <p className="text-xs font-bold mb-2">Dr. {n.doctorName} • {n.date}</p>
                  <p className="text-sm italic text-slate-600">"{n.note}"</p>
                </div>
              ))}
             </div>
          </RecordCard>

          {showAddModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
              <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl">
                <h3 className="text-xl font-bold mb-6">New Medical Entry</h3>
                <form onSubmit={(e) => {
                  e.preventDefault();
                  const f = new FormData(e.currentTarget);
                  if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
                  if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency'), prescribedBy: f.get('doc') });
                  if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note') });
                }} className="space-y-4">
                  {showAddModal === 'problem' && (
                    <>
                      <input required name="condition" placeholder="Condition (e.g. Hypertension)" className="w-full p-3 border rounded-xl" />
                      <select name="severity" className="w-full p-3 border rounded-xl">
                        <option value="mild">Mild</option>
                        <option value="moderate">Moderate</option>
                        <option value="severe">Severe</option>
                      </select>
                      <input required type="date" name="onsetDate" className="w-full p-3 border rounded-xl" />
                      <input type="hidden" name="status" value="present" />
                    </>
                  )}
                  {showAddModal === 'med' && (
                    <>
                      <input required name="name" placeholder="Medication Name" className="w-full p-3 border rounded-xl" />
                      <div className="grid grid-cols-2 gap-2">
                        <input required name="dosage" placeholder="500mg" className="w-full p-3 border rounded-xl" />
                        <input required name="frequency" placeholder="1-0-1" className="w-full p-3 border rounded-xl" />
                      </div>
                      <input name="doc" placeholder="Prescribed By Dr." className="w-full p-3 border rounded-xl" />
                    </>
                  )}
                  {showAddModal === 'note' && (
                    <>
                      <input required name="doc" placeholder="Doctor's Name" className="w-full p-3 border rounded-xl" />
                      <input required type="date" name="date" className="w-full p-3 border rounded-xl" />
                      <textarea required name="note" placeholder="Observations..." className="w-full p-3 border rounded-xl h-32"></textarea>
                    </>
                  )}
                  <div className="flex gap-2">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-3 bg-slate-100 font-bold rounded-xl">Cancel</button>
                    <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl">Save</button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}
      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
          <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
             <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-2xl text-sm">
                <p className="font-bold text-indigo-900 mb-1">August AI</p>
                <p className="text-indigo-800 opacity-80 italic mb-2">Analyzing: {currentUser?.profile.name}'s ({currentUser?.profile.bloodGroup}) Profile...</p>
                <p className="text-xs text-indigo-600">I can warn you about medicine conflicts, analyze your condition severity, or give lifestyle advice.</p>
             </div>
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 border border-slate-100 text-slate-800'}`}>
                    {m.content}
                  </div>
               </div>
             ))}
             {isAiLoading && <div className="text-xs text-slate-400 italic px-4">August is thinking...</div>}
          </div>
          <div className="flex gap-2 border-t pt-4">
            <input value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} placeholder="Ask about medicine conflicts or diet..." className="flex-grow p-4 bg-slate-100 rounded-2xl outline-none" />
            <button onClick={askAugustAI} disabled={isAiLoading || !userQuery.trim()} className="px-6 bg-indigo-600 text-white font-bold rounded-2xl disabled:opacity-50">Send</button>
          </div>
        </div>
      )}
      {activeTab === 'history' && (
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
             <h3 className="text-xl font-bold mb-4">Universal Record Search</h3>
             <div className="flex gap-4">
                <input value={searchId} onChange={(e) => setSearchId(e.target.value)} className="flex-grow p-4 border rounded-2xl font-mono" placeholder="HID-XXXX-XXXX" />
                <button onClick={handleSearch} className="px-8 bg-slate-800 text-white font-bold rounded-2xl">Search</button>
             </div>
          </div>
          {searchResults && (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4">
              <div className="bg-indigo-900 p-6 text-white flex justify-between items-center">
                <div>
                  <h4 className="text-xl font-bold">{searchResults.profile.name}</h4>
                  <p className="text-xs opacity-60 font-mono">{searchResults.profile.healthId}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs font-bold px-3 py-1 bg-white/10 rounded-full">{searchResults.profile.bloodGroup}</p>
                </div>
              </div>
              <div className="p-8 grid md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <h5 className="text-[10px] font-bold text-slate-400 uppercase">Current Medications</h5>
                  {searchResults.medications.map(m => <div key={m.id} className="p-3 bg-slate-50 rounded-xl font-bold text-sm">{m.name} ({m.dosage})</div>)}
                </div>
                <div className="space-y-4">
                  <h5 className="text-[10px] font-bold text-slate-400 uppercase">Emergency Contact</h5>
                  <div className="p-3 border rounded-xl">
                    <p className="font-bold text-indigo-700">{searchResults.profile.emergencyContact.name}</p>
                    <p className="text-xs text-slate-500">{searchResults.profile.emergencyContact.phone}</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  useEffect(() => {
    const savedRecords = localStorage.getItem(STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let loadedRecords: HealthRecord[] = [];
    if (savedRecords) {
      loadedRecords = JSON.parse(savedRecords);
      setAllRecords(loadedRecords);
    }
    if (activeSession && loadedRecords.length > 0) {
      const found = loadedRecords.find(r => r.profile.healthId === activeSession);
      if (found) {
        setCurrentUser(found);
        setIsAuth(true);
      }
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: formData.get('name') as string,
      age: parseInt(formData.get('age') as string),
      dob: formData.get('dob') as string,
      phone: formData.get('phone') as string,
      aadhaar: formData.get('aadhaar') as string,
      bloodGroup: formData.get('bloodGroup') as string,
      emergencyContact: {
        name: formData.get('eName') as string,
        phone: formData.get('ePhone') as string
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsAuth(true);
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === loginId.trim().toUpperCase());
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Verify your ID format.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    // STRICT DEDUPLICATION LOGIC
    const collection = currentUser[type] as any[];
    const isDuplicate = collection.some((existing: any) => {
      if (type === 'problems') return existing.condition.toLowerCase() === item.condition.toLowerCase();
      if (type === 'medications') return existing.name.toLowerCase() === item.name.toLowerCase();
      if (type === 'allergies') return existing.substance.toLowerCase() === item.substance.toLowerCase();
      if (type === 'surgeries') return existing.type.toLowerCase() === item.type.toLowerCase() && existing.date === item.date;
      return false;
    });

    if (isDuplicate) {
      alert(`This ${type.slice(0, -1)} is already present in your secure record.`);
      return;
    }

    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);
    const updatedAll = allRecords.map(r => r.profile.healthId === currentUser.profile.healthId ? updatedUser : r);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === searchId.trim().toUpperCase());
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8">Secure digital health records with proactive AI guidance.</p>
              <div className="space-y-4">
                <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                  <p className="text-xs font-bold uppercase tracking-wider text-indigo-200 mb-2">Security Standard</p>
                  <p className="text-sm">End-to-end encryption for Aadhaar and clinical notes.</p>
                </div>
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center">
            <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-2 text-sm font-semibold rounded-lg ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-2 text-sm font-semibold rounded-lg ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
            </div>
            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold">{authError}</div>}
            {authMode === 'register' ? (
              <form onSubmit={handleRegister} className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                    <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="John Doe" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                    <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                    <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200">
                      {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                  <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="XXXX XXXX XXXX" />
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl space-y-3 border border-slate-100">
                  <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                  <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Name" />
                  <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Phone" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg">Create Health Wallet</button>
              </form>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono tracking-widest" placeholder="HID-XXXX-XXXX" />
                <button type="submit" className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl">Unlock Records</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} onLogout={handleLogout}>
      {activeTab === 'dashboard' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-gradient-to-r from-indigo-600 to-indigo-800 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
              <div className="relative z-10">
                <p className="text-indigo-200 text-xs font-bold uppercase mb-4 tracking-widest">Active Health Passport</p>
                <div className="flex items-end justify-between">
                  <h1 className="text-4xl font-mono font-bold tracking-tighter">{currentUser?.profile.healthId}</h1>
                  <div className="bg-white/20 px-4 py-2 rounded-xl backdrop-blur-md">
                    <p className="text-[10px] font-bold opacity-60 uppercase">Blood Group</p>
                    <p className="text-xl font-bold">{currentUser?.profile.bloodGroup}</p>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                  <div>
                    <p className="text-xs text-indigo-200 uppercase font-bold">Emergency Contact</p>
                    <p className="font-bold">{currentUser?.profile.emergencyContact.name} • {currentUser?.profile.emergencyContact.phone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-indigo-200 uppercase font-bold">Age / DOB</p>
                    <p className="font-bold">{currentUser?.profile.age} Yrs / {currentUser?.profile.dob}</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col justify-between">
              <h3 className="text-slate-400 text-xs font-bold uppercase tracking-widest">Health Snapshot</h3>
              <div className="space-y-3 mt-4">
                <div className="flex justify-between p-3 bg-rose-50 rounded-2xl">
                  <span className="text-xs font-bold text-rose-700">Allergies</span>
                  <span className="font-black text-rose-800">{currentUser?.allergies.length}</span>
                </div>
                <div className="flex justify-between p-3 bg-blue-50 rounded-2xl">
                  <span className="text-xs font-bold text-blue-700">Active Meds</span>
                  <span className="font-black text-blue-800">{currentUser?.medications.length}</span>
                </div>
                <div className="flex justify-between p-3 bg-emerald-50 rounded-2xl">
                  <span className="text-xs font-bold text-emerald-700">Surgeries</span>
                  <span className="font-black text-emerald-800">{currentUser?.surgeries.length}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <RecordCard title="Medical Problems" icon={ICONS.MEDICAL}>
              {currentUser?.problems.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No conditions recorded.</p>
              ) : currentUser?.problems.filter(p => p.status === 'present').map(p => (
                <div key={p.id} className="flex justify-between items-center p-3 border-b border-slate-50 last:border-0">
                  <div>
                    <p className="font-bold text-slate-800">{p.condition}</p>
                    <p className="text-[10px] text-slate-400">Since {p.onsetDate}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-[10px] font-bold ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{p.severity?.toUpperCase()}</span>
                </div>
              ))}
            </RecordCard>
            <RecordCard title="Latest Treatment History" icon={ICONS.NOTE}>
               {currentUser?.notes.length === 0 ? (
                 <p className="text-xs text-slate-400 italic">No treatment history available.</p>
               ) : (
                 <div className="p-3 bg-indigo-50/50 rounded-2xl">
                    <p className="text-[10px] font-bold text-indigo-600 mb-1">DR. {currentUser?.notes[currentUser.notes.length-1].doctorName.toUpperCase()}</p>
                    <p className="text-sm text-slate-700 italic">"{currentUser?.notes[currentUser.notes.length-1].note}"</p>
                    <p className="text-[10px] text-slate-400 mt-2 text-right">{currentUser?.notes[currentUser.notes.length-1].date}</p>
                 </div>
               )}
            </RecordCard>
          </div>
        </div>
      )}
      {activeTab === 'records' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 pb-20">
          <RecordCard title="Conditions & Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
            <div className="space-y-2">
              {currentUser?.problems.map(p => (
                <div key={p.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                  <div>
                    <span className="font-bold text-slate-800">{p.condition}</span>
                    <p className="text-[10px] text-slate-400">{p.severity?.toUpperCase()} Severity</p>
                  </div>
                  <span className="text-[10px] bg-white px-2 py-1 rounded-full border font-bold text-slate-500">{p.status.toUpperCase()}</span>
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
            <div className="space-y-2">
              {currentUser?.medications.map(m => (
                <div key={m.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                  <div>
                    <span className="font-bold text-slate-800">{m.name}</span>
                    <p className="text-[10px] text-slate-500">{m.frequency}</p>
                  </div>
                  <span className="text-xs font-bold text-indigo-600">{m.dosage}</span>
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Operations & Surgeries" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
            <div className="space-y-2">
              {currentUser?.surgeries.map(s => (
                <div key={s.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                  <div className="flex justify-between items-center mb-1">
                    <span className="font-bold text-slate-800">{s.type}</span>
                    <span className="text-[10px] font-bold text-slate-400">{s.date}</span>
                  </div>
                  <p className="text-[10px] text-indigo-500 font-semibold">{s.hospital}</p>
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Allergies" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
            <div className="flex flex-wrap gap-2">
              {currentUser?.allergies.map(a => (
                <div key={a.id} className="px-3 py-1 bg-rose-50 border border-rose-100 rounded-full text-[11px] font-bold text-rose-700">
                  {a.substance} ({a.severity.toUpperCase()})
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Treatment History & Doctor Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {currentUser?.notes.map(n => (
                <div key={n.id} className="p-4 bg-indigo-50/30 rounded-2xl border border-indigo-100 relative group transition-all hover:shadow-md">
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-xs font-bold text-indigo-900 uppercase tracking-wider">Dr. {n.doctorName}</p>
                    <p className="text-[10px] text-slate-400 font-bold">{n.date}</p>
                  </div>
                  <p className="text-sm italic text-slate-600 leading-relaxed">"{n.note}"</p>
                  {n.clinicName && <p className="mt-2 text-[10px] font-bold text-indigo-400">{n.clinicName.toUpperCase()}</p>}
                </div>
              ))}
             </div>
          </RecordCard>

          {showAddModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
              <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative">
                <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600">
                  <i className="fas fa-times text-xl"></i>
                </button>
                <h3 className="text-xl font-bold mb-6 text-slate-800">Add {showAddModal.charAt(0).toUpperCase() + showAddModal.slice(1)} Record</h3>
                <form onSubmit={(e) => {
                  e.preventDefault();
                  const f = new FormData(e.currentTarget);
                  if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
                  if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency'), prescribedBy: f.get('doc') });
                  if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
                  if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity') });
                  if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
                }} className="space-y-4">
                  {showAddModal === 'problem' && (
                    <>
                      <input required name="condition" placeholder="Condition Name" className="w-full p-3 border rounded-xl" />
                      <div className="grid grid-cols-2 gap-2">
                        <select name="severity" className="w-full p-3 border rounded-xl">
                          <option value="mild">Mild</option>
                          <option value="moderate">Moderate</option>
                          <option value="severe">Severe</option>
                        </select>
                        <select name="status" className="w-full p-3 border rounded-xl">
                          <option value="present">Present</option>
                          <option value="past">Past</option>
                        </select>
                      </div>
                      <input required type="date" name="onsetDate" className="w-full p-3 border rounded-xl" />
                    </>
                  )}
                  {showAddModal === 'med' && (
                    <>
                      <input required name="name" placeholder="Medicine Name" className="w-full p-3 border rounded-xl" />
                      <div className="grid grid-cols-2 gap-2">
                        <input required name="dosage" placeholder="Dosage (500mg)" className="w-full p-3 border rounded-xl" />
                        <input required name="frequency" placeholder="Frequency (1-0-1)" className="w-full p-3 border rounded-xl" />
                      </div>
                      <input name="duration" placeholder="Duration (7 days)" className="w-full p-3 border rounded-xl" />
                      <input name="doc" placeholder="Prescribed By Dr." className="w-full p-3 border rounded-xl" />
                    </>
                  )}
                  {showAddModal === 'surgery' && (
                    <>
                      <input required name="type" placeholder="Procedure / Surgery Type" className="w-full p-3 border rounded-xl" />
                      <input required type="date" name="date" className="w-full p-3 border rounded-xl" />
                      <input required name="hospital" placeholder="Hospital / Medical Center" className="w-full p-3 border rounded-xl" />
                    </>
                  )}
                  {showAddModal === 'allergy' && (
                    <>
                      <input required name="substance" placeholder="Allergen (e.g. Penicillin)" className="w-full p-3 border rounded-xl" />
                      <select name="severity" className="w-full p-3 border rounded-xl">
                        <option value="low">Low</option>
                        <option value="moderate">Moderate</option>
                        <option value="high">High</option>
                      </select>
                    </>
                  )}
                  {showAddModal === 'note' && (
                    <>
                      <div className="grid grid-cols-2 gap-2">
                        <input required name="doc" placeholder="Doctor's Name" className="w-full p-3 border rounded-xl" />
                        <input required type="date" name="date" className="w-full p-3 border rounded-xl" />
                      </div>
                      <input name="clinic" placeholder="Clinic / Hospital Name" className="w-full p-3 border rounded-xl" />
                      <textarea required name="note" placeholder="Treatment Plan / Doctor Observations..." className="w-full p-3 border rounded-xl h-32"></textarea>
                    </>
                  )}
                  <div className="flex gap-2 pt-2">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 font-bold rounded-xl transition-colors hover:bg-slate-200">Cancel</button>
                    <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl transition-all hover:bg-indigo-700 shadow-lg shadow-indigo-100">Save Record</button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}
      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
          <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
             <div className="p-5 bg-indigo-50 border border-indigo-100 rounded-3xl text-sm relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-100/30 rounded-full -mr-16 -mt-16"></div>
                <p className="font-bold text-indigo-900 mb-1 flex items-center">
                  <span className="mr-2">{ICONS.AI}</span> August AI Medical Assistant
                </p>
                <p className="text-indigo-800 opacity-80 italic mb-2">Patient Profile Loaded: {currentUser?.profile.name}</p>
                <p className="text-xs text-indigo-600 font-medium">I've analyzed your {currentUser?.problems.length} conditions and {currentUser?.medications.length} medications. How can I help today?</p>
             </div>
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 border border-slate-100 text-slate-800'}`}>
                    {m.content}
                  </div>
               </div>
             ))}
             {isAiLoading && <div className="text-xs text-slate-400 font-bold animate-pulse px-4">August is carefully analyzing your medical records...</div>}
          </div>
          <div className="flex gap-3 border-t border-slate-50 pt-4">
            <input 
              value={userQuery} 
              onChange={(e) => setUserQuery(e.target.value)} 
              onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} 
              placeholder="Ask about side effects, diet, or surgery history..." 
              className="flex-grow p-4 bg-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm" 
            />
            <button 
              onClick={askAugustAI} 
              disabled={isAiLoading || !userQuery.trim()} 
              className="px-6 bg-indigo-600 text-white font-bold rounded-2xl disabled:opacity-50 transition-all hover:bg-indigo-700 shadow-lg shadow-indigo-100"
            >
              Ask AI
            </button>
          </div>
        </div>
      )}
      {activeTab === 'history' && (
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
             <h3 className="text-xl font-bold mb-4 text-slate-800">Universal Digital Memory Search</h3>
             <p className="text-slate-500 text-sm mb-6">Fetch medical history for any registered patient using their unique Health ID.</p>
             <div className="flex flex-col md:flex-row gap-4">
                <input 
                  value={searchId} 
                  onChange={(e) => setSearchId(e.target.value)} 
                  className="flex-grow p-4 border border-slate-200 rounded-2xl font-mono tracking-widest outline-none focus:ring-2 focus:ring-indigo-500" 
                  placeholder="HID-XXXX-XXXX" 
                />
                <button 
                  onClick={handleSearch} 
                  className="px-8 py-4 bg-slate-800 text-white font-bold rounded-2xl transition-all hover:bg-black"
                >
                  Retrieve Records
                </button>
             </div>
          </div>
          {searchResults && (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-indigo-900 p-8 text-white flex justify-between items-center relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
                <div className="relative z-10">
                  <h4 className="text-2xl font-bold">{searchResults.profile.name}</h4>
                  <p className="text-sm opacity-60 font-mono tracking-widest">{searchResults.profile.healthId}</p>
                </div>
                <div className="text-right relative z-10">
                  <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-300">Blood Group</p>
                  <p className="text-2xl font-bold">{searchResults.profile.bloodGroup}</p>
                </div>
              </div>
              <div className="p-8 grid md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center">
                      <span className="mr-2 text-indigo-600">{ICONS.MEDS}</span> Active Medications
                    </h5>
                    {searchResults.medications.length > 0 ? (
                      <div className="space-y-2">
                        {searchResults.medications.map(m => (
                          <div key={m.id} className="p-3 bg-slate-50 rounded-xl font-bold text-sm border border-slate-100">
                            {m.name} <span className="text-indigo-600 ml-2">({m.dosage})</span>
                          </div>
                        ))}
                      </div>
                    ) : <p className="text-xs text-slate-400 italic">No medication history.</p>}
                  </div>
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center">
                      <span className="mr-2 text-indigo-600">{ICONS.SURGERY}</span> Surgery History
                    </h5>
                    <div className="space-y-2">
                      {searchResults.surgeries.map(s => (
                        <div key={s.id} className="p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100">
                          {s.type} • {s.date}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
                <div className="space-y-6">
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center">
                      <span className="mr-2 text-rose-500">{ICONS.ALLERGY}</span> Allergic Reactions
                    </h5>
                    <div className="flex flex-wrap gap-2">
                      {searchResults.allergies.map(a => (
                        <span key={a.id} className="px-3 py-1 bg-rose-50 text-rose-600 border border-rose-100 rounded-full text-[10px] font-bold">{a.substance.toUpperCase()}</span>
                      ))}
                    </div>
                  </div>
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center">
                      <span className="mr-2 text-indigo-600">{ICONS.USER}</span> Emergency SOS
                    </h5>
                    <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-2xl">
                      <p className="font-bold text-indigo-900">{searchResults.profile.emergencyContact.name}</p>
                      <p className="text-xs font-bold text-indigo-600">{searchResults.profile.emergencyContact.phone}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  useEffect(() => {
    const savedRecords = localStorage.getItem(STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let loadedRecords: HealthRecord[] = [];
    if (savedRecords) {
      loadedRecords = JSON.parse(savedRecords);
      setAllRecords(loadedRecords);
    }
    if (activeSession && loadedRecords.length > 0) {
      const found = loadedRecords.find(r => r.profile.healthId === activeSession);
      if (found) {
        setCurrentUser(found);
        setIsAuth(true);
      }
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: formData.get('name') as string,
      age: parseInt(formData.get('age') as string),
      dob: formData.get('dob') as string,
      phone: formData.get('phone') as string,
      aadhaar: formData.get('aadhaar') as string,
      bloodGroup: formData.get('bloodGroup') as string,
      emergencyContact: {
        name: formData.get('eName') as string,
        phone: formData.get('ePhone') as string
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsAuth(true);
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === loginId.trim().toUpperCase());
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Verify your ID format.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    const collection = currentUser[type] as any[];
    const isDuplicate = collection.some((existing: any) => {
      if (type === 'problems') return existing.condition.toLowerCase() === item.condition.toLowerCase();
      if (type === 'medications') return existing.name.toLowerCase() === item.name.toLowerCase();
      if (type === 'allergies') return existing.substance.toLowerCase() === item.substance.toLowerCase();
      if (type === 'surgeries') return existing.type.toLowerCase() === item.type.toLowerCase() && existing.date === item.date;
      return false;
    });

    if (isDuplicate) {
      alert(`This ${type.slice(0, -1)} is already present in your secure record.`);
      return;
    }

    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);
    const updatedAll = allRecords.map(r => r.profile.healthId === currentUser.profile.healthId ? updatedUser : r);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const handleExportJSON = () => {
    if (!currentUser) return;
    const dataStr = JSON.stringify(currentUser, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `HealthRecord_${currentUser.profile.healthId}_${Date.now()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportPDF = () => {
    window.print();
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === searchId.trim().toUpperCase());
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8">Secure digital health records with proactive AI guidance.</p>
              <div className="space-y-4">
                <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                  <p className="text-xs font-bold uppercase tracking-wider text-indigo-200 mb-2">Security Standard</p>
                  <p className="text-sm">End-to-end encryption for Aadhaar and clinical notes.</p>
                </div>
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center">
            <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-2 text-sm font-semibold rounded-lg ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-2 text-sm font-semibold rounded-lg ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
            </div>
            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold">{authError}</div>}
            {authMode === 'register' ? (
              <form onSubmit={handleRegister} className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                    <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="John Doe" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                    <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                    <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200">
                      {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                  <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="XXXX XXXX XXXX" />
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl space-y-3 border border-slate-100">
                  <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                  <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Name" />
                  <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Phone" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg">Create Health Wallet</button>
              </form>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono tracking-widest" placeholder="HID-XXXX-XXXX" />
                <button type="submit" className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl">Unlock Records</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} onLogout={handleLogout}>
      <style>
        {`
          @media print {
            body { background: white !important; }
            aside, header, footer, button, .no-print { display: none !important; }
            main { margin: 0 !important; width: 100% !important; }
            .print-only { display: block !important; }
            .print-container { padding: 20px; }
            .grid { display: block !important; }
            .rounded-3xl, .rounded-2xl { border-radius: 0 !important; border: 1px solid #eee !important; }
            .shadow-xl, .shadow-sm { box-shadow: none !important; }
          }
        `}
      </style>

      {/* DASHBOARD TAB */}
      {activeTab === 'dashboard' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-gradient-to-r from-indigo-600 to-indigo-800 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
              <div className="relative z-10">
                <p className="text-indigo-200 text-xs font-bold uppercase mb-4 tracking-widest">Active Health Passport</p>
                <div className="flex items-end justify-between">
                  <h1 className="text-4xl font-mono font-bold tracking-tighter">{currentUser?.profile.healthId}</h1>
                  <div className="bg-white/20 px-4 py-2 rounded-xl backdrop-blur-md">
                    <p className="text-[10px] font-bold opacity-60 uppercase">Blood Group</p>
                    <p className="text-xl font-bold">{currentUser?.profile.bloodGroup}</p>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                  <div>
                    <p className="text-xs text-indigo-200 uppercase font-bold">Emergency Contact</p>
                    <p className="font-bold">{currentUser?.profile.emergencyContact.name} • {currentUser?.profile.emergencyContact.phone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-indigo-200 uppercase font-bold">Age / DOB</p>
                    <p className="font-bold">{currentUser?.profile.age} Yrs / {currentUser?.profile.dob}</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col justify-between">
              <h3 className="text-slate-400 text-xs font-bold uppercase tracking-widest">Health Snapshot</h3>
              <div className="space-y-3 mt-4">
                <div className="flex justify-between p-3 bg-rose-50 rounded-2xl">
                  <span className="text-xs font-bold text-rose-700">Allergies</span>
                  <span className="font-black text-rose-800">{currentUser?.allergies.length}</span>
                </div>
                <div className="flex justify-between p-3 bg-blue-50 rounded-2xl">
                  <span className="text-xs font-bold text-blue-700">Active Meds</span>
                  <span className="font-black text-blue-800">{currentUser?.medications.length}</span>
                </div>
                <div className="flex justify-between p-3 bg-emerald-50 rounded-2xl">
                  <span className="text-xs font-bold text-emerald-700">Surgeries</span>
                  <span className="font-black text-emerald-800">{currentUser?.surgeries.length}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <RecordCard title="Medical Problems" icon={ICONS.MEDICAL}>
              {currentUser?.problems.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No conditions recorded.</p>
              ) : currentUser?.problems.filter(p => p.status === 'present').map(p => (
                <div key={p.id} className="flex justify-between items-center p-3 border-b border-slate-50 last:border-0">
                  <div>
                    <p className="font-bold text-slate-800">{p.condition}</p>
                    <p className="text-[10px] text-slate-400">Since {p.onsetDate}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-[10px] font-bold ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{p.severity?.toUpperCase()}</span>
                </div>
              ))}
            </RecordCard>
            <RecordCard title="Latest Treatment History" icon={ICONS.NOTE}>
               {currentUser?.notes.length === 0 ? (
                 <p className="text-xs text-slate-400 italic">No treatment history available.</p>
               ) : (
                 <div className="p-3 bg-indigo-50/50 rounded-2xl">
                    <p className="text-[10px] font-bold text-indigo-600 mb-1">DR. {currentUser?.notes[currentUser.notes.length-1].doctorName.toUpperCase()}</p>
                    <p className="text-sm text-slate-700 italic">"{currentUser?.notes[currentUser.notes.length-1].note}"</p>
                    <p className="text-[10px] text-slate-400 mt-2 text-right">{currentUser?.notes[currentUser.notes.length-1].date}</p>
                 </div>
               )}
            </RecordCard>
          </div>
        </div>
      )}

      {/* RECORDS TAB */}
      {activeTab === 'records' && (
        <div className="space-y-6 pb-20">
          {/* Export Control Panel */}
          <div className="bg-indigo-900 rounded-3xl p-6 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6 no-print">
            <div className="flex items-center space-x-4">
              <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-2xl">
                <i className="fas fa-file-export"></i>
              </div>
              <div>
                <h3 className="font-bold text-lg">Secure Export Hub</h3>
                <p className="text-xs text-indigo-200">Download your entire medical memory for doctors or travel.</p>
              </div>
            </div>
            <div className="flex items-center space-x-3 w-full md:w-auto">
              <button 
                onClick={handleExportJSON}
                className="flex-1 md:flex-none px-6 py-3 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-sm transition-all border border-white/10"
              >
                JSON Export
              </button>
              <button 
                onClick={handleExportPDF}
                className="flex-1 md:flex-none px-6 py-3 bg-white text-indigo-900 hover:bg-indigo-50 rounded-xl font-bold text-sm transition-all shadow-lg"
              >
                Print Health PDF
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <RecordCard title="Conditions & Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
              <div className="space-y-2">
                {currentUser?.problems.map(p => (
                  <div key={p.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                    <div>
                      <span className="font-bold text-slate-800">{p.condition}</span>
                      <p className="text-[10px] text-slate-400">{p.severity?.toUpperCase()} Severity</p>
                    </div>
                    <span className="text-[10px] bg-white px-2 py-1 rounded-full border font-bold text-slate-500">{p.status.toUpperCase()}</span>
                  </div>
                ))}
                {currentUser?.problems.length === 0 && <p className="text-xs text-slate-400 italic text-center py-4">No conditions added.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
              <div className="space-y-2">
                {currentUser?.medications.map(m => (
                  <div key={m.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                    <div>
                      <span className="font-bold text-slate-800">{m.name}</span>
                      <p className="text-[10px] text-slate-500">{m.frequency}</p>
                    </div>
                    <span className="text-xs font-bold text-indigo-600">{m.dosage}</span>
                  </div>
                ))}
                {currentUser?.medications.length === 0 && <p className="text-xs text-slate-400 italic text-center py-4">No medications added.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Operations & Surgeries" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
              <div className="space-y-2">
                {currentUser?.surgeries.map(s => (
                  <div key={s.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <div className="flex justify-between items-center mb-1">
                      <span className="font-bold text-slate-800">{s.type}</span>
                      <span className="text-[10px] font-bold text-slate-400">{s.date}</span>
                    </div>
                    <p className="text-[10px] text-indigo-500 font-semibold">{s.hospital}</p>
                  </div>
                ))}
                {currentUser?.surgeries.length === 0 && <p className="text-xs text-slate-400 italic text-center py-4">No surgeries recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Allergies" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
              <div className="flex flex-wrap gap-2">
                {currentUser?.allergies.map(a => (
                  <div key={a.id} className="px-3 py-1 bg-rose-50 border border-rose-100 rounded-full text-[11px] font-bold text-rose-700">
                    {a.substance} ({a.severity.toUpperCase()})
                  </div>
                ))}
                {currentUser?.allergies.length === 0 && <p className="text-xs text-slate-400 italic py-4">No allergies recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Treatment History & Doctor Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {currentUser?.notes.map(n => (
                  <div key={n.id} className="p-4 bg-indigo-50/30 rounded-2xl border border-indigo-100 relative group transition-all hover:shadow-md">
                    <div className="flex items-center justify-between mb-2">
                      <p className="text-xs font-bold text-indigo-900 uppercase tracking-wider">Dr. {n.doctorName}</p>
                      <p className="text-[10px] text-slate-400 font-bold">{n.date}</p>
                    </div>
                    <p className="text-sm italic text-slate-600 leading-relaxed">"{n.note}"</p>
                    {n.clinicName && <p className="mt-2 text-[10px] font-bold text-indigo-400">{n.clinicName.toUpperCase()}</p>}
                  </div>
                ))}
                {currentUser?.notes.length === 0 && <p className="col-span-2 text-xs text-slate-400 italic text-center py-4">No notes recorded yet.</p>}
              </div>
            </RecordCard>
          </div>

          {/* Modal Overlay for Adding Records */}
          {showAddModal && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200 no-print">
              <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative">
                <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600">
                  <i className="fas fa-times text-xl"></i>
                </button>
                <h3 className="text-xl font-bold mb-6 text-slate-800">Add {showAddModal.charAt(0).toUpperCase() + showAddModal.slice(1)} Record</h3>
                <form onSubmit={(e) => {
                  e.preventDefault();
                  const f = new FormData(e.currentTarget);
                  if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
                  if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency'), prescribedBy: f.get('doc') });
                  if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
                  if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity') });
                  if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
                }} className="space-y-4">
                  {showAddModal === 'problem' && (
                    <>
                      <input required name="condition" placeholder="Condition Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <div className="grid grid-cols-2 gap-2">
                        <select name="severity" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
                          <option value="mild">Mild</option>
                          <option value="moderate">Moderate</option>
                          <option value="severe">Severe</option>
                        </select>
                        <select name="status" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
                          <option value="present">Present</option>
                          <option value="past">Past</option>
                        </select>
                      </div>
                      <input required type="date" name="onsetDate" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                    </>
                  )}
                  {showAddModal === 'med' && (
                    <>
                      <input required name="name" placeholder="Medicine Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <div className="grid grid-cols-2 gap-2">
                        <input required name="dosage" placeholder="Dosage (500mg)" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                        <input required name="frequency" placeholder="Frequency (1-0-1)" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                      <input name="duration" placeholder="Duration (7 days)" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <input name="doc" placeholder="Prescribed By Dr." className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                    </>
                  )}
                  {showAddModal === 'surgery' && (
                    <>
                      <input required name="type" placeholder="Procedure / Surgery Type" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <input required type="date" name="date" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <input required name="hospital" placeholder="Hospital / Medical Center" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                    </>
                  )}
                  {showAddModal === 'allergy' && (
                    <>
                      <input required name="substance" placeholder="Allergen (e.g. Penicillin)" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <select name="severity" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500">
                        <option value="low">Low</option>
                        <option value="moderate">Moderate</option>
                        <option value="high">High</option>
                      </select>
                    </>
                  )}
                  {showAddModal === 'note' && (
                    <>
                      <div className="grid grid-cols-2 gap-2">
                        <input required name="doc" placeholder="Doctor's Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                        <input required type="date" name="date" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                      <input name="clinic" placeholder="Clinic / Hospital Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                      <textarea required name="note" placeholder="Treatment Plan / Doctor Observations..." className="w-full p-3 border rounded-xl h-32 outline-none focus:ring-2 focus:ring-indigo-500"></textarea>
                    </>
                  )}
                  <div className="flex gap-2 pt-2">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 font-bold rounded-xl transition-colors hover:bg-slate-200">Cancel</button>
                    <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl transition-all hover:bg-indigo-700 shadow-lg shadow-indigo-100">Save Record</button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* AUGUST AI TAB */}
      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100 no-print">
          <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
             <div className="p-5 bg-indigo-50 border border-indigo-100 rounded-3xl text-sm relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-100/30 rounded-full -mr-16 -mt-16"></div>
                <p className="font-bold text-indigo-900 mb-1 flex items-center">
                  <span className="mr-2">{ICONS.AI}</span> August AI Medical Assistant
                </p>
                <p className="text-indigo-800 opacity-80 italic mb-2">Patient Profile Loaded: {currentUser?.profile.name}</p>
                <p className="text-xs text-indigo-600 font-medium">I've analyzed your {currentUser?.problems.length} conditions and {currentUser?.medications.length} medications. How can I help today?</p>
             </div>
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 border border-slate-100 text-slate-800'}`}>
                    {m.content}
