import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedRecords = localStorage.getItem(STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let loadedRecords: HealthRecord[] = [];
    if (savedRecords) {
      try {
        loadedRecords = JSON.parse(savedRecords);
        setAllRecords(loadedRecords);
      } catch (e) {
        console.error("Failed to parse local records", e);
      }
    }
    if (activeSession && loadedRecords.length > 0) {
      const found = loadedRecords.find(r => r.profile.healthId === activeSession);
      if (found) {
        setCurrentUser(found);
        setIsAuth(true);
      }
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: formData.get('name') as string,
      age: parseInt(formData.get('age') as string),
      dob: formData.get('dob') as string,
      phone: formData.get('phone') as string,
      aadhaar: formData.get('aadhaar') as string,
      bloodGroup: formData.get('bloodGroup') as string,
      emergencyContact: {
        name: formData.get('eName') as string,
        phone: formData.get('ePhone') as string
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsAuth(true);
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === loginId.trim().toUpperCase());
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Verify your ID format.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    const collection = currentUser[type] as any[];
    const isDuplicate = collection.some((existing: any) => {
      if (type === 'problems') return existing.condition.toLowerCase() === item.condition.toLowerCase();
      if (type === 'medications') return existing.name.toLowerCase() === item.name.toLowerCase();
      if (type === 'allergies') return existing.substance.toLowerCase() === item.substance.toLowerCase();
      if (type === 'surgeries') return existing.type.toLowerCase() === item.type.toLowerCase() && existing.date === item.date;
      return false;
    });

    if (isDuplicate) {
      alert(`This ${type.slice(0, -1)} is already present in your record.`);
      return;
    }

    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);
    const updatedAll = allRecords.map(r => r.profile.healthId === currentUser.profile.healthId ? updatedUser : r);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const handleExportJSON = () => {
    if (!currentUser) return;
    const dataStr = JSON.stringify(currentUser, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `HealthRecord_${currentUser.profile.healthId}_${Date.now()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const importedRecord = JSON.parse(event.target?.result as string) as HealthRecord;
        if (!importedRecord.profile?.healthId) throw new Error("Invalid Record Format");

        const existingIndex = allRecords.findIndex(r => r.profile.healthId === importedRecord.profile.healthId);
        let updatedAll = [...allRecords];

        if (existingIndex > -1) {
          if (confirm("This Health ID already exists. Overwrite with imported data?")) {
            updatedAll[existingIndex] = importedRecord;
          } else {
            return;
          }
        } else {
          updatedAll.push(importedRecord);
        }

        saveAllRecords(updatedAll);
        setCurrentUser(importedRecord);
        localStorage.setItem(SESSION_KEY, importedRecord.profile.healthId);
        setIsAuth(true);
        alert("Record imported successfully!");
      } catch (err) {
        alert("Failed to import record. Ensure the file is a valid HealthShield JSON export.");
      }
    };
    reader.readAsText(file);
  };

  const handleExportPDF = () => {
    window.print();
  };

  const calculateCompletion = () => {
    if (!currentUser) return 0;
    const metrics = [
      currentUser.problems.length > 0,
      currentUser.medications.length > 0,
      currentUser.surgeries.length > 0,
      currentUser.allergies.length > 0,
      currentUser.notes.length > 0,
      !!currentUser.profile.bloodGroup,
      !!currentUser.profile.emergencyContact.name
    ];
    const completed = metrics.filter(Boolean).length;
    return Math.round((completed / metrics.length) * 100);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const found = allRecords.find(r => r.profile.healthId.trim().toUpperCase() === searchId.trim().toUpperCase());
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4 tracking-tight">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8 leading-relaxed">Secure digital health records with proactive AI guidance and encrypted vault storage.</p>
              <div className="space-y-4">
                <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                  <p className="text-xs font-bold uppercase tracking-wider text-indigo-200 mb-2">Security Standard</p>
                  <p className="text-sm">End-to-end encryption for health identification and clinical notes.</p>
                </div>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-3 bg-white/10 hover:bg-white/20 border border-white/20 rounded-xl text-sm font-bold transition-all text-white flex items-center justify-center gap-2"
                >
                  <i className="fas fa-file-import"></i> Restore from Export File
                </button>
                <input type="file" ref={fileInputRef} onChange={handleImportJSON} className="hidden" accept=".json" />
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center">
            <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
            </div>
            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold animate-pulse">{authError}</div>}
            {authMode === 'register' ? (
              <form onSubmit={handleRegister} className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                    <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="John Doe" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                    <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                    <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500">
                      {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                  <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="XXXX XXXX XXXX" />
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl space-y-3 border border-slate-100">
                  <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                  <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Name" />
                  <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Phone" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition-all">Create Health Wallet</button>
              </form>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono tracking-widest outline-none focus:ring-2 focus:ring-indigo-500" placeholder="HID-XXXX-XXXX" />
                <button type="submit" className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl hover:bg-black transition-all">Unlock Records</button>
              </form>
            )}
          </div>
        </div>
      </div>
    );
  }

  const completionScore = calculateCompletion();

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile.name || ''} onLogout={handleLogout}>
      <style>
        {`
          @media print {
            body { background: white !important; }
            aside, header, footer, button, .no-print { display: none !important; }
            main { margin: 0 !important; width: 100% !important; padding: 0 !important; }
            .print-only { display: block !important; }
            .print-container { padding: 40px; }
            .grid { display: block !important; }
            .rounded-3xl, .rounded-2xl { border-radius: 0 !important; border: 1px solid #eee !important; box-shadow: none !important; }
            .shadow-xl, .shadow-sm { box-shadow: none !important; }
          }
        `}
      </style>

      {activeTab === 'dashboard' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-gradient-to-r from-indigo-600 to-indigo-800 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
              <div className="relative z-10">
                <p className="text-indigo-200 text-xs font-bold uppercase mb-4 tracking-widest">Active Health Passport</p>
                <div className="flex items-end justify-between">
                  <h1 className="text-4xl font-mono font-bold tracking-tighter">{currentUser?.profile.healthId}</h1>
                  <div className="bg-white/20 px-4 py-2 rounded-xl backdrop-blur-md">
                    <p className="text-[10px] font-bold opacity-60 uppercase">Blood Group</p>
                    <p className="text-xl font-bold">{currentUser?.profile.bloodGroup}</p>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                  <div>
                    <p className="text-xs text-indigo-200 uppercase font-bold">Emergency Contact</p>
                    <p className="font-bold">{currentUser?.profile.emergencyContact.name} • {currentUser?.profile.emergencyContact.phone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-indigo-200 uppercase font-bold">Age / DOB</p>
                    <p className="font-bold">{currentUser?.profile.age} Yrs / {currentUser?.profile.dob}</p>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <h3 className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-4">Record Completion</h3>
              <div className="relative w-32 h-32 flex items-center justify-center mb-4">
                 <svg className="w-full h-full transform -rotate-90">
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={364.4} strokeDashoffset={364.4 - (364.4 * completionScore) / 100} strokeLinecap="round" className="text-indigo-600 transition-all duration-1000" />
                 </svg>
                 <span className="absolute text-2xl font-black text-slate-800">{completionScore}%</span>
              </div>
              <p className="text-xs font-medium text-slate-500 leading-relaxed px-4">
                {completionScore === 100 ? "Excellent! Your health data is fully recorded." : "Continue adding records to ensure a complete medical memory."}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-rose-50 p-6 rounded-3xl border border-rose-100">
               <p className="text-[10px] font-bold text-rose-400 uppercase tracking-widest mb-1">Allergies</p>
               <p className="text-3xl font-black text-rose-700">{currentUser?.allergies.length}</p>
            </div>
            <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100">
               <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mb-1">Active Meds</p>
               <p className="text-3xl font-black text-blue-700">{currentUser?.medications.length}</p>
            </div>
            <div className="bg-emerald-50 p-6 rounded-3xl border border-emerald-100">
               <p className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest mb-1">Procedures</p>
               <p className="text-3xl font-black text-emerald-700">{currentUser?.surgeries.length}</p>
            </div>
            <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
               <p className="text-[10px] font-bold text-amber-400 uppercase tracking-widest mb-1">Clinician Notes</p>
               <p className="text-3xl font-black text-amber-700">{currentUser?.notes.length}</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <RecordCard title="Medical Problems" icon={ICONS.MEDICAL}>
              {currentUser?.problems.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No conditions recorded.</p>
              ) : currentUser?.problems.filter(p => p.status === 'present').map(p => (
                <div key={p.id} className="flex justify-between items-center p-3 border-b border-slate-50 last:border-0">
                  <div>
                    <p className="font-bold text-slate-800">{p.condition}</p>
                    <p className="text-[10px] text-slate-400">Since {p.onsetDate}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-[10px] font-bold ${p.severity === 'severe' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{p.severity?.toUpperCase()}</span>
                </div>
              ))}
            </RecordCard>
            <RecordCard title="Latest Treatment History" icon={ICONS.NOTE}>
               {currentUser?.notes.length === 0 ? (
                 <p className="text-xs text-slate-400 italic">No treatment history available.</p>
               ) : (
                 <div className="p-3 bg-indigo-50/50 rounded-2xl">
                    <p className="text-[10px] font-bold text-indigo-600 mb-1">DR. {currentUser?.notes[currentUser.notes.length-1].doctorName.toUpperCase()}</p>
                    <p className="text-sm text-slate-700 italic leading-relaxed">"{currentUser?.notes[currentUser.notes.length-1].note}"</p>
                    <p className="text-[10px] text-slate-400 mt-2 text-right">{currentUser?.notes[currentUser.notes.length-1].date}</p>
                 </div>
               )}
            </RecordCard>
          </div>
        </div>
      )}

      {activeTab === 'records' && (
        <div className="space-y-6 pb-20 no-print">
          <div className="bg-indigo-900 rounded-3xl p-8 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16"></div>
            <div className="flex items-center space-x-6 relative z-10">
              <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center text-3xl shadow-inner">
                <i className="fas fa-database"></i>
              </div>
              <div>
                <h3 className="font-bold text-xl mb-1">Record Management Center</h3>
                <p className="text-xs text-indigo-200 max-w-sm">Securely back up your Health ID data or restore records from an external encrypted file.</p>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto relative z-10">
              <button onClick={() => fileInputRef.current?.click()} className="flex-1 md:flex-none px-6 py-4 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-xs transition-all border border-white/10 flex items-center justify-center gap-2">
                <i className="fas fa-file-import"></i> Restore Record
              </button>
              <button onClick={handleExportJSON} className="flex-1 md:flex-none px-6 py-4 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-xs transition-all border border-white/10 flex items-center justify-center gap-2">
                <i className="fas fa-download"></i> Backup JSON
              </button>
              <button onClick={handleExportPDF} className="flex-1 md:flex-none px-6 py-4 bg-white text-indigo-900 hover:bg-indigo-50 rounded-xl font-bold text-xs transition-all shadow-lg flex items-center justify-center gap-2">
                <i className="fas fa-print"></i> Print Records
              </button>
              <input type="file" ref={fileInputRef} onChange={handleImportJSON} className="hidden" accept=".json" />
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <RecordCard title="Conditions & Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
              <div className="space-y-2">
                {currentUser?.problems.map(p => (
                  <div key={p.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                    <div>
                      <span className="font-bold text-slate-800">{p.condition}</span>
                      <p className="text-[10px] text-slate-400">{p.severity?.toUpperCase()} Severity</p>
                    </div>
                    <span className="text-[10px] bg-white px-2 py-1 rounded-full border font-bold text-slate-500">{p.status.toUpperCase()}</span>
                  </div>
                ))}
                {currentUser?.problems.length === 0 && <p className="text-center py-4 text-xs text-slate-400">Click '+ ADD NEW' to record conditions.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
              <div className="space-y-2">
                {currentUser?.medications.map(m => (
                  <div key={m.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                    <div>
                      <span className="font-bold text-slate-800">{m.name}</span>
                      <p className="text-[10px] text-slate-500">{m.frequency}</p>
                    </div>
                    <span className="text-xs font-bold text-indigo-600">{m.dosage}</span>
                  </div>
                ))}
                {currentUser?.medications.length === 0 && <p className="text-center py-4 text-xs text-slate-400">No active medications recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Surgeries & Procedures" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
              <div className="space-y-2">
                {currentUser?.surgeries.map(s => (
                  <div key={s.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <div className="flex justify-between items-center mb-1">
                      <span className="font-bold text-slate-800">{s.type}</span>
                      <span className="text-[10px] font-bold text-slate-400">{s.date}</span>
                    </div>
                    <p className="text-[10px] text-indigo-500 font-semibold">{s.hospital}</p>
                  </div>
                ))}
              </div>
            </RecordCard>

            <RecordCard title="Allergic Reactions" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
              <div className="flex flex-wrap gap-2">
                {currentUser?.allergies.map(a => (
                  <div key={a.id} className="px-3 py-1 bg-rose-50 border border-rose-100 rounded-full text-[11px] font-bold text-rose-700">{a.substance} ({a.severity.toUpperCase()})</div>
                ))}
                {currentUser?.allergies.length === 0 && <p className="w-full text-center py-4 text-xs text-slate-400">No allergies recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Doctor Consultations & Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {currentUser?.notes.map(n => (
                  <div key={n.id} className="p-4 bg-indigo-50/30 rounded-2xl border border-indigo-100 relative group transition-all hover:shadow-md">
                    <div className="flex items-center justify-between mb-2">
                      <p className="text-xs font-bold text-indigo-900 uppercase tracking-wider">Dr. {n.doctorName}</p>
                      <p className="text-[10px] text-slate-400 font-bold">{n.date}</p>
                    </div>
                    <p className="text-sm italic text-slate-600 leading-relaxed">"{n.note}"</p>
                  </div>
                ))}
              </div>
            </RecordCard>
          </div>
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm no-print">
          <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative animate-in zoom-in duration-200">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600 transition-colors"><i className="fas fa-times text-xl"></i></button>
            <h3 className="text-xl font-bold mb-6 text-slate-800">Record {showAddModal.charAt(0).toUpperCase() + showAddModal.slice(1)}</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
              if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency'), prescribedBy: f.get('doc') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="e.g., Type 2 Diabetes" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-2">
                    <select name="severity" className="w-full p-3 border rounded-xl outline-none"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select>
                    <select name="status" className="w-full p-3 border rounded-xl outline-none"><option value="present">Present</option><option value="past">Past</option></select>
                  </div>
                  <input required type="date" name="onsetDate" className="w-full p-3 border rounded-xl outline-none" />
                </>
              )}
              {showAddModal === 'med' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="dosage" placeholder="Dosage (e.g., 10mg)" className="w-full p-3 border rounded-xl" />
                    <input required name="frequency" placeholder="Freq (e.g., 1-0-1)" className="w-full p-3 border rounded-xl" />
                  </div>
                  <input name="doc" placeholder="Prescribed By" className="w-full p-3 border rounded-xl" />
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="doc" placeholder="Doctor's Name" className="w-full p-3 border rounded-xl outline-none" />
                    <input required type="date" name="date" className="w-full p-3 border rounded-xl outline-none" />
                  </div>
                  <textarea required name="note" placeholder="Consultation notes, symptoms, or instructions..." className="w-full p-3 border rounded-xl h-32 outline-none focus:ring-2 focus:ring-indigo-500"></textarea>
                </>
              )}
              <div className="flex gap-2 pt-2">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-3 bg-slate-100 font-bold rounded-xl text-slate-500 hover:bg-slate-200 transition-all">Cancel</button>
                <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 transition-all">Save Record</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100 no-print">
          <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
             <div className="p-5 bg-indigo-50 border border-indigo-100 rounded-3xl text-sm relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-100/30 rounded-full -mr-16 -mt-16"></div>
                <p className="font-bold text-indigo-900 mb-1 flex items-center"><span className="mr-2">{ICONS.AI}</span> August AI Assistant</p>
                <p className="text-xs text-indigo-600 font-medium leading-relaxed italic">I've analyzed your medical profile and HID details. How can I assist you with your health record today?</p>
             </div>
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 border border-slate-100 text-slate-800'}`}>{m.content}</div>
               </div>
             ))}
             {isAiLoading && <div className="text-xs text-slate-400 font-bold px-4 animate-pulse">August is analyzing all HID data...</div>}
          </div>
          <div className="flex gap-3 border-t border-slate-50 pt-4">
            <input value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} placeholder="Ask about medicine interactions, completion steps..." className="flex-grow p-4 bg-slate-100 rounded-2xl outline-none text-sm focus:ring-2 focus:ring-indigo-500 transition-all" />
            <button onClick={askAugustAI} disabled={isAiLoading || !userQuery.trim()} className="px-6 bg-indigo-600 text-white font-bold rounded-2xl disabled:opacity-50 transition-all hover:bg-indigo-700 shadow-lg">Analyze</button>
          </div>
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-6 no-print">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
             <h3 className="text-xl font-bold mb-4 text-slate-800">Universal Digital Memory Search</h3>
             <p className="text-slate-500 text-sm mb-6">Search for and view medical data from any verified Health ID in the vault.</p>
             <div className="flex flex-col md:flex-row gap-4">
                <input value={searchId} onChange={(e) => setSearchId(e.target.value)} className="flex-grow p-4 border border-slate-200 rounded-2xl font-mono tracking-widest outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="HID-XXXX-XXXX" />
                <button onClick={handleSearch} className="px-8 py-4 bg-slate-800 text-white font-bold rounded-2xl transition-all hover:bg-black shadow-lg">Retrieve Record</button>
             </div>
          </div>
          {searchResults && (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-indigo-900 p-8 text-white flex justify-between items-center relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
                <div className="relative z-10">
                  <h4 className="text-2xl font-bold mb-1">{searchResults.profile.name}</h4>
                  <p className="text-sm opacity-60 font-mono tracking-widest">{searchResults.profile.healthId}</p>
                </div>
                <div className="text-right relative z-10">
                  <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-300">Blood Group</p>
                  <p className="text-2xl font-bold">{searchResults.profile.bloodGroup}</p>
                </div>
              </div>
              <div className="p-8 grid md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Active Medications</h5>
                    {searchResults.medications.length > 0 ? searchResults.medications.map(m => (
                      <div key={m.id} className="p-3 bg-slate-50 rounded-xl font-bold text-sm border mb-2">{m.name} ({m.dosage})</div>
                    )) : <p className="text-xs text-slate-400 italic">None recorded.</p>}
                  </div>
                </div>
                <div className="space-y-6">
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Emergency Contact</h5>
                    <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-2xl">
                      <p className="font-bold text-indigo-900">{searchResults.profile.emergencyContact.name}</p>
                      <p className="text-xs font-bold text-indigo-600">{searchResults.profile.emergencyContact.phone}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {currentUser && (
        <div className="hidden print-only print-container">
          <div className="border-b-4 border-indigo-900 pb-6 mb-8 flex justify-between items-end">
            <div>
              <h1 className="text-3xl font-bold text-indigo-900 uppercase tracking-tight">HealthShield Official Record</h1>
              <p className="text-slate-500 font-bold tracking-widest font-mono">{currentUser.profile.healthId}</p>
            </div>
            <p className="text-xs font-bold text-slate-400 uppercase text-right">Export Date: {new Date().toLocaleDateString()}</p>
          </div>
          <div className="grid grid-cols-2 gap-8 mb-8">
            <div className="p-6 bg-slate-50 border rounded-2xl">
              <h2 className="text-xs font-bold text-indigo-600 uppercase mb-4 tracking-widest">Patient Identification</h2>
              <div className="space-y-2 text-sm">
                <p><span className="text-slate-400">Full Name:</span> <span className="font-bold">{currentUser.profile.name}</span></p>
                <p><span className="text-slate-400">DOB:</span> <span className="font-bold">{currentUser.profile.dob}</span></p>
                <p><span className="text-slate-400">Blood Group:</span> <span className="font-bold">{currentUser.profile.bloodGroup}</span></p>
                <p><span className="text-slate-400">Emergency:</span> <span className="font-bold">{currentUser.profile.emergencyContact.name} ({currentUser.profile.emergencyContact.phone})</span></p>
              </div>
            </div>
          </div>
          <div className="space-y-8">
            <section><h3 className="text-lg font-bold border-b pb-2 mb-4">Medical Conditions</h3>{currentUser.problems.map(p => <div key={p.id} className="py-2 border-b flex justify-between"><span className="font-bold">{p.condition}</span><span>{p.onsetDate}</span></div>)}</section>
            <section><h3 className="text-lg font-bold border-b pb-2 mb-4">Current Medications</h3>{currentUser.medications.map(m => <div key={m.id} className="py-2 border-b"><p className="font-bold">{m.name} - {m.dosage}</p><p className="text-xs">{m.frequency}</p></div>)}</section>
            <section><h3 className="text-lg font-bold border-b pb-2 mb-4">Clinical Notes</h3>{currentUser.notes.map(n => <div key={n.id} className="py-3 border-b"><p className="text-xs font-bold">DR. {n.doctorName} • {n.date}</p><p className="text-sm italic text-slate-600 leading-relaxed">"{n.note}"</p></div>)}</section>
          </div>
          <div className="mt-20 pt-8 border-t text-[10px] text-slate-400 text-center uppercase tracking-widest italic">End of Official Secure HealthShield Record</div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, AI_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedRecords = localStorage.getItem(STORAGE_KEY);
    const activeSession = localStorage.getItem(SESSION_KEY);
    let loadedRecords: HealthRecord[] = [];
    if (savedRecords) {
      try {
        loadedRecords = JSON.parse(savedRecords);
        setAllRecords(loadedRecords);
      } catch (e) {
        console.error("Failed to parse local records", e);
      }
    }
    if (activeSession && loadedRecords.length > 0) {
      const found = loadedRecords.find(r => r.profile?.healthId === activeSession);
      if (found) {
        setCurrentUser(found);
        setIsAuth(true);
      }
    }
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    const updated = [...allRecords, newRecord];
    saveAllRecords(updated);
    setCurrentUser(newRecord);
    localStorage.setItem(SESSION_KEY, healthId);
    setIsAuth(true);
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    const inputId = (loginId || '').trim().toUpperCase();
    const found = allRecords.find(r => (r.profile?.healthId || '').trim().toUpperCase() === inputId);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Verify your ID format.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    const collection = currentUser[type] as any[];
    const isDuplicate = collection.some((existing: any) => {
      const compare = (val: any) => (val || '').toString().toLowerCase();
      if (type === 'problems') return compare(existing.condition) === compare(item.condition);
      if (type === 'medications') return compare(existing.name) === compare(item.name);
      if (type === 'allergies') return compare(existing.substance) === compare(item.substance);
      if (type === 'surgeries') return compare(existing.type) === compare(item.type) && existing.date === item.date;
      return false;
    });

    if (isDuplicate) {
      alert(`This ${type.slice(0, -1)} is already present in your record.`);
      return;
    }

    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);
    const updatedAll = allRecords.map(r => r.profile.healthId === currentUser.profile.healthId ? updatedUser : r);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const handleExportJSON = () => {
    if (!currentUser) return;
    const dataStr = JSON.stringify(currentUser, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `HealthRecord_${currentUser.profile.healthId}_${Date.now()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const importedRecord = JSON.parse(event.target?.result as string) as HealthRecord;
        if (!importedRecord.profile?.healthId) throw new Error("Invalid Record Format");

        const existingIndex = allRecords.findIndex(r => r.profile?.healthId === importedRecord.profile.healthId);
        let updatedAll = [...allRecords];

        if (existingIndex > -1) {
          if (confirm("This Health ID already exists. Overwrite with imported data?")) {
            updatedAll[existingIndex] = importedRecord;
          } else {
            return;
          }
        } else {
          updatedAll.push(importedRecord);
        }

        saveAllRecords(updatedAll);
        setCurrentUser(importedRecord);
        localStorage.setItem(SESSION_KEY, importedRecord.profile.healthId);
        setIsAuth(true);
        alert("Record imported successfully!");
      } catch (err) {
        alert("Failed to import record. Ensure the file is a valid HealthShield JSON export.");
      }
    };
    reader.readAsText(file);
  };

  const handleExportPDF = () => {
    window.print();
  };

  const calculateCompletion = () => {
    if (!currentUser) return 0;
    const metrics = [
      (currentUser.problems || []).length > 0,
      (currentUser.medications || []).length > 0,
      (currentUser.surgeries || []).length > 0,
      (currentUser.allergies || []).length > 0,
      (currentUser.notes || []).length > 0,
      !!currentUser.profile?.bloodGroup,
      !!currentUser.profile?.emergencyContact?.name
    ];
    const completed = metrics.filter(Boolean).length;
    return Math.round((completed / metrics.length) * 100);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const inputId = (searchId || '').trim().toUpperCase();
    const found = allRecords.find(r => (r.profile?.healthId || '').trim().toUpperCase() === inputId);
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4 tracking-tight">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8 leading-relaxed">Secure digital health records with proactive AI guidance and encrypted vault storage.</p>
              <div className="space-y-4">
                <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                  <p className="text-xs font-bold uppercase tracking-wider text-indigo-200 mb-2">Security Standard</p>
                  <p className="text-sm">End-to-end encryption for health identification and clinical notes.</p>
                </div>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-3 bg-white/10 hover:bg-white/20 border border-white/20 rounded-xl text-sm font-bold transition-all text-white flex items-center justify-center gap-2"
                >
                  <i className="fas fa-file-import"></i> Restore from Export File
                </button>
                <input type="file" ref={fileInputRef} onChange={handleImportJSON} className="hidden" accept=".json" />
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center">
            <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
            </div>
            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold animate-pulse">{authError}</div>}
            {authMode === 'register' ? (
              <form onSubmit={handleRegister} className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                    <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="John Doe" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                    <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                    <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500">
                      {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
