export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);
  const [copyFeedback, setCopyFeedback] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load records on initial mount
  useEffect(() => {
    const loadData = () => {
      const savedRecords = localStorage.getItem(STORAGE_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      if (savedRecords) {
        try {
          const loadedRecords = JSON.parse(savedRecords);
          setAllRecords(loadedRecords);
          if (activeSession) {
            const found = loadedRecords.find((r: HealthRecord) => r.profile?.healthId === activeSession);
            if (found) {
              setCurrentUser(found);
              setIsAuth(true);
            }
          }
        } catch (e) {
          console.error("Failed to parse local records", e);
        }
      }
    };
    loadData();
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    // Use a fresh copy of current records from storage to avoid state stale closure
    const currentStored = localStorage.getItem(STORAGE_KEY);
    const existingRecords = currentStored ? JSON.parse(currentStored) : [];
    const updated = [...existingRecords, newRecord];

    saveAllRecords(updated);
    localStorage.setItem(LAST_HID_KEY, healthId);
    setShowRegSuccess(healthId);
  };

  const completeRegistration = () => {
    if (!showRegSuccess) return;
    const found = allRecords.find(r => r.profile?.healthId === showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');

    // SOURCE OF TRUTH: Read directly from localStorage to ensure we have the most recent registration
    const currentStored = localStorage.getItem(STORAGE_KEY);
    if (!currentStored) {
      setAuthError("No records found in this vault. Please register first.");
      return;
    }

    const records: HealthRecord[] = JSON.parse(currentStored);
    const inputId = (loginId || '').trim().toUpperCase();

    const found = records.find(r => (r.profile?.healthId || '').trim().toUpperCase() === inputId);

    if (found) {
      setCurrentUser(found);
      setAllRecords(records); // Sync state with storage
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Ensure you copied the full ID correctly (HID-XXXX-XXXX).");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopyFeedback(true);
    setTimeout(() => setCopyFeedback(false), 2000);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    const collection = (currentUser[type] as any[]) || [];
    const isDuplicate = collection.some((existing: any) => {
      const compare = (val: any) => (val || '').toString().toLowerCase();
      if (type === 'problems') return compare(existing.condition) === compare(item.condition);
      if (type === 'medications') return compare(existing.name) === compare(item.name);
      if (type === 'allergies') return compare(existing.substance) === compare(item.substance);
      if (type === 'surgeries') return compare(existing.type) === compare(item.type) && existing.date === item.date;
      return false;
    });

    if (isDuplicate) {
      alert(`This ${type.slice(0, -1)} is already present.`);
      return;
    }

    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    setCurrentUser(updatedUser);
    const updatedAll = allRecords.map(r => r.profile.healthId === currentUser.profile.healthId ? updatedUser : r);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const handleExportJSON = () => {
    if (!currentUser) return;
    const dataStr = JSON.stringify(currentUser, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `HealthShield_${currentUser.profile.healthId}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const importedRecord = JSON.parse(event.target?.result as string) as HealthRecord;
        if (!importedRecord.profile?.healthId) throw new Error("Invalid Format");
        const existingRecords = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
        const existingIndex = existingRecords.findIndex((r: HealthRecord) => r.profile?.healthId === importedRecord.profile.healthId);
        let updatedAll = [...existingRecords];
        if (existingIndex > -1) {
          if (confirm("ID exists. Overwrite?")) updatedAll[existingIndex] = importedRecord;
          else return;
        } else {
          updatedAll.push(importedRecord);
        }
        saveAllRecords(updatedAll);
        setCurrentUser(importedRecord);
        localStorage.setItem(SESSION_KEY, importedRecord.profile.healthId);
        setIsAuth(true);
        alert("Imported!");
      } catch (err) {
        alert("Import failed.");
      }
    };
    reader.readAsText(file);
  };

  // Function to handle browser-based PDF generation (trigger print dialog)
  const handleExportPDF = () => {
    window.print();
  };

  const completionScore = (() => {
    if (!currentUser) return 0;
    const metrics = [
      (currentUser.problems || []).length > 0,
      (currentUser.medications || []).length > 0,
      (currentUser.surgeries || []).length > 0,
      (currentUser.allergies || []).length > 0,
      (currentUser.notes || []).length > 0,
      !!currentUser.profile?.bloodGroup,
      !!currentUser.profile?.emergencyContact?.name
    ];
    return Math.round((metrics.filter(Boolean).length / metrics.length) * 100);
  })();

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const inputId = (searchId || '').trim().toUpperCase();
    const found = allRecords.find(r => (r.profile?.healthId || '').trim().toUpperCase() === inputId);
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100 min-h-[600px]">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4 tracking-tight">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8 leading-relaxed">Secure medical storage with instant AI insights. Access your clinical history anywhere with your unique ID.</p>
              <div className="space-y-4">
                <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                  <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-200 mb-2">Security Note</p>
                  <p className="text-sm">Records are stored locally in your browser's secure vault and never uploaded to external servers without your action.</p>
                </div>
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center">
            <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
              <button onClick={() => setAuthMode('register')} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
              <button onClick={() => setAuthMode('login')} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
            </div>

            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold border border-red-100">{authError}</div>}

            {authMode === 'register' ? (
              <form onSubmit={handleRegister} className="space-y-4 max-h-[450px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-200">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                    <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Patient Name" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                    <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                    <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                    <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500">
                      {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                  <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="XXXX XXXX XXXX" />
                </div>
                <div className="p-4 bg-indigo-50/50 rounded-2xl space-y-3 border border-indigo-100">
                  <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                  <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white outline-none" placeholder="Contact Name" />
                  <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white outline-none" placeholder="Contact Phone" />
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition-all transform active:scale-[0.98]">Generate Health ID</button>
              </form>
            ) : (
              <form onSubmit={handleLogin} className="space-y-6">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Enter Your Secure Health ID</label>
                  <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono tracking-widest outline-none focus:ring-2 focus:ring-indigo-500 transition-all uppercase" placeholder="HID-XXXX-XXXX" />
                  {localStorage.getItem(LAST_HID_KEY) && (
                    <button type="button" onClick={() => setLoginId(localStorage.getItem(LAST_HID_KEY) || '')} className="mt-2 text-[10px] font-bold text-indigo-500 hover:text-indigo-700 uppercase tracking-tighter">
                      Use Last Created: {localStorage.getItem(LAST_HID_KEY)}
                    </button>
                  )}
                </div>
                <button type="submit" className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl hover:bg-black transition-all shadow-lg transform active:scale-[0.98]">Unlock Records</button>
              </form>
            )}
          </div>
        </div>

        {/* REGISTRATION SUCCESS MODAL */}
        {showRegSuccess && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
            <div className="bg-white max-w-md w-full rounded-3xl p-8 shadow-2xl text-center animate-in zoom-in duration-300">
              <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-3xl mx-auto mb-6">
                <i className="fas fa-check-circle"></i>
              </div>
              <h3 className="text-2xl font-bold text-slate-800 mb-2">Health ID Created!</h3>
              <p className="text-slate-500 text-sm mb-6 leading-relaxed">Please copy and save your unique Health ID. You will need this to log in again.</p>

              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center justify-between mb-8 group">
                <span className="font-mono font-bold text-indigo-600 text-lg tracking-widest">{showRegSuccess}</span>
                <button 
                  onClick={() => copyToClipboard(showRegSuccess)}
                  className={`p-2 rounded-lg transition-all ${copyFeedback ? 'bg-emerald-500 text-white' : 'bg-white text-indigo-600 hover:bg-indigo-50 border border-slate-200'}`}
                >
                  <i className={`fas ${copyFeedback ? 'fa-check' : 'fa-copy'}`}></i>
                </button>
              </div>

              <button 
                onClick={completeRegistration}
                className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg hover:bg-indigo-700 transition-all"
              >
                Access My Dashboard
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout}>
      <style>
        {`
          @media print {
            body { background: white !important; }
            aside, header, footer, button, .no-print { display: none !important; }
            main { margin: 0 !important; width: 100% !important; padding: 0 !important; }
            .print-only { display: block !important; }
            .print-container { padding: 40px; }
            .grid { display: block !important; }
            .rounded-3xl, .rounded-2xl { border-radius: 0 !important; border: 1px solid #eee !important; box-shadow: none !important; }
          }
        `}
      </style>

      {activeTab === 'dashboard' && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
              <div className="relative z-10">
                <p className="text-indigo-200 text-[10px] font-bold uppercase mb-4 tracking-widest">Digital Health Passport</p>
                <div className="flex items-end justify-between">
                  <div>
                    <h1 className="text-4xl font-mono font-bold tracking-tighter mb-1">{currentUser?.profile?.healthId}</h1>
                    <button 
                      onClick={() => currentUser && copyToClipboard(currentUser.profile.healthId)}
                      className="text-[10px] font-bold text-indigo-300 hover:text-white uppercase tracking-widest flex items-center"
                    >
                      <i className="fas fa-copy mr-1"></i> {copyFeedback ? 'Copied' : 'Copy ID'}
                    </button>
                  </div>
                  <div className="bg-white/10 px-4 py-2 rounded-xl backdrop-blur-md border border-white/10">
                    <p className="text-[8px] font-bold opacity-60 uppercase tracking-tighter">Blood Type</p>
                    <p className="text-xl font-bold">{currentUser?.profile?.bloodGroup || 'N/A'}</p>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                  <div>
                    <p className="text-[10px] text-indigo-300 uppercase font-bold tracking-tighter mb-1">Emergency SOS</p>
                    <p className="font-bold text-sm">{currentUser?.profile?.emergencyContact?.name} • {currentUser?.profile?.emergencyContact?.phone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] text-indigo-300 uppercase font-bold tracking-tighter mb-1">Identification</p>
                    <p className="font-bold text-sm">Age {currentUser?.profile?.age} • DOB {currentUser?.profile?.dob}</p>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <h3 className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-4">Vault Completion</h3>
              <div className="relative w-32 h-32 flex items-center justify-center mb-4">
                 <svg className="w-full h-full transform -rotate-90">
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={364.4} strokeDashoffset={364.4 - (364.4 * completionScore) / 100} strokeLinecap="round" className="text-indigo-600 transition-all duration-700" />
                 </svg>
                 <span className="absolute text-2xl font-black text-slate-800">{completionScore}%</span>
              </div>
              <p className="text-[10px] font-bold text-slate-400 leading-relaxed uppercase tracking-tighter">
                {completionScore === 100 ? "Full Record Secured" : "Data recording in progress"}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.ALLERGY}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Allergies</p><p className="text-xl font-black text-slate-800">{(currentUser?.allergies || []).length}</p></div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.MEDS}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Active Meds</p><p className="text-xl font-black text-slate-800">{(currentUser?.medications || []).length}</p></div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.SURGERY}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Procedures</p><p className="text-xl font-black text-slate-800">{(currentUser?.surgeries || []).length}</p></div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.NOTE}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Notes</p><p className="text-xl font-black text-slate-800">{(currentUser?.notes || []).length}</p></div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <RecordCard title="Medical Conditions" icon={ICONS.MEDICAL}>
              {(!currentUser?.problems || currentUser.problems.length === 0) ? (
                <p className="text-xs text-slate-400 italic py-4">No conditions recorded.</p>
              ) : currentUser.problems.filter(p => p.status === 'present').map(p => (
                <div key={p.id} className="flex justify-between items-center p-3 border-b border-slate-50 last:border-0">
                  <div>
                    <p className="font-bold text-slate-800 text-sm">{p.condition}</p>
                    <p className="text-[10px] text-slate-400">Since {p.onsetDate}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-[10px] font-bold ${(p.severity || '').toLowerCase() === 'severe' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{(p.severity || 'N/A').toUpperCase()}</span>
                </div>
              ))}
            </RecordCard>
            <RecordCard title="Latest Clinical Notes" icon={ICONS.NOTE}>
               {(!currentUser?.notes || currentUser.notes.length === 0) ? (
                 <p className="text-xs text-slate-400 italic py-4">No treatment history available.</p>
               ) : (
                 <div className="p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                    <p className="text-[10px] font-bold text-indigo-600 mb-2 flex justify-between uppercase tracking-tighter">
                      <span>DR. {(currentUser.notes[currentUser.notes.length-1].doctorName || 'Unknown').toUpperCase()}</span>
                      <span className="opacity-60">{currentUser.notes[currentUser.notes.length-1].date}</span>
                    </p>
                    <p className="text-sm text-slate-700 italic leading-relaxed">"{currentUser.notes[currentUser.notes.length-1].note || 'No notes available'}"</p>
                 </div>
               )}
            </RecordCard>
          </div>
        </div>
      )}

      {activeTab === 'records' && (
        <div className="space-y-6 pb-20 no-print animate-in slide-in-from-right-4 duration-500">
          <div className="bg-slate-900 rounded-3xl p-8 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16"></div>
            <div className="flex items-center space-x-6 relative z-10">
              <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center text-3xl shadow-inner text-indigo-300">
                <i className="fas fa-database"></i>
              </div>
              <div>
                <h3 className="font-bold text-xl mb-1">Secure Vault Actions</h3>
                <p className="text-xs text-slate-400 max-w-sm">Manage your encrypted records locally or export them for external sharing.</p>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto relative z-10">
              <button onClick={() => fileInputRef.current?.click()} className="flex-1 md:flex-none px-6 py-4 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-xs transition-all border border-white/10 flex items-center justify-center gap-2">
                <i className="fas fa-file-import"></i> Restore Record
              </button>
              <button onClick={handleExportJSON} className="flex-1 md:flex-none px-6 py-4 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-xs transition-all border border-white/10 flex items-center justify-center gap-2">
                <i className="fas fa-download"></i> Backup JSON
              </button>
              <button onClick={handleExportPDF} className="flex-1 md:flex-none px-6 py-4 bg-indigo-600 text-white hover:bg-indigo-700 rounded-xl font-bold text-xs transition-all shadow-lg flex items-center justify-center gap-2">
                <i className="fas fa-print"></i> Print PDF
              </button>
              <input type="file" ref={fileInputRef} onChange={handleImportJSON} className="hidden" accept=".json" />
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <RecordCard title="Conditions & Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
              <div className="space-y-2">
                {(currentUser?.problems || []).map(p => (
                  <div key={p.id} className="p-4 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100 hover:bg-white transition-all">
                    <div>
                      <span className="font-bold text-slate-800">{p.condition}</span>
                      <p className="text-[10px] text-slate-400">{(p.severity || 'mild').toUpperCase()} • {p.onsetDate}</p>
                    </div>
                    <span className="text-[10px] bg-indigo-50 px-2 py-1 rounded-full border border-indigo-100 font-bold text-indigo-600">{(p.status || 'present').toUpperCase()}</span>
                  </div>
                ))}
                {(!currentUser?.problems || currentUser.problems.length === 0) && <p className="text-center py-6 text-xs text-slate-400">No conditions recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
              <div className="space-y-2">
                {(currentUser?.medications || []).map(m => (
                  <div key={m.id} className="p-4 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                    <div>
                      <span className="font-bold text-slate-800">{m.name}</span>
                      <p className="text-[10px] text-slate-500">{m.frequency} • {m.duration}</p>
                    </div>
                    <span className="text-xs font-bold text-indigo-600 px-3 py-1 bg-white rounded-lg border border-slate-100">{m.dosage}</span>
                  </div>
                ))}
                {(!currentUser?.medications || currentUser.medications.length === 0) && <p className="text-center py-6 text-xs text-slate-400">No active medications.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Surgeries & Procedures" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
              <div className="space-y-2">
                {(currentUser?.surgeries || []).map(s => (
                  <div key={s.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                    <div className="flex justify-between items-center mb-1">
                      <span className="font-bold text-slate-800">{s.type}</span>
                      <span className="text-[10px] font-bold text-slate-400">{s.date}</span>
                    </div>
                    <p className="text-[10px] text-indigo-500 font-semibold">{s.hospital}</p>
                  </div>
                ))}
                {(!currentUser?.surgeries || currentUser.surgeries.length === 0) && <p className="text-center py-6 text-xs text-slate-400">No surgical history.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Allergic Reactions" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
              <div className="flex flex-wrap gap-2">
                {(currentUser?.allergies || []).map(a => (
                  <div key={a.id} className="px-3 py-1 bg-rose-50 border border-rose-100 rounded-full text-[11px] font-bold text-rose-700 flex items-center">
                    <span className="w-1.5 h-1.5 bg-rose-500 rounded-full mr-2"></span>
                    {(a.substance || '').toUpperCase()} ({(a.severity || '').toUpperCase()})
                  </div>
                ))}
                {(!currentUser?.allergies || currentUser.allergies.length === 0) && <p className="w-full text-center py-6 text-xs text-slate-400">No allergies recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Clinical Consultation Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(currentUser?.notes || []).map(n => (
                  <div key={n.id} className="p-5 bg-indigo-50/30 rounded-2xl border border-indigo-100 transition-all hover:shadow-md hover:bg-white">
                    <div className="flex items-center justify-between mb-3">
                      <p className="text-xs font-bold text-indigo-900 uppercase tracking-widest">Dr. {n.doctorName}</p>
                      <p className="text-[10px] text-slate-400 font-bold">{n.date}</p>
                    </div>
                    <p className="text-sm italic text-slate-600 leading-relaxed">"{n.note}"</p>
                  </div>
                ))}
                {(!currentUser?.notes || currentUser.notes.length === 0) && <p className="col-span-2 text-center py-10 text-xs text-slate-400">Clinical notes vault is empty.</p>}
              </div>
            </RecordCard>
          </div>
        </div>
      )}

      {/* ADD ITEM MODAL */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600 transition-colors"><i className="fas fa-times text-xl"></i></button>
            <h3 className="text-xl font-bold mb-6 text-slate-800">Add {showAddModal.charAt(0).toUpperCase() + showAddModal.slice(1)} Record</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
              if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency'), prescribedBy: f.get('doc') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-2">
                    <select name="severity" className="w-full p-3 border rounded-xl outline-none"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select>
                    <select name="status" className="w-full p-3 border rounded-xl outline-none"><option value="present">Present</option><option value="past">Past</option></select>
                  </div>
                  <input required type="date" name="onsetDate" className="w-full p-3 border rounded-xl outline-none" />
                </>
              )}
              {showAddModal === 'med' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="dosage" placeholder="Dosage (500mg)" className="w-full p-3 border rounded-xl" />
                    <input required name="frequency" placeholder="Freq (1-0-1)" className="w-full p-3 border rounded-xl" />
                  </div>
                  <input name="duration" placeholder="Duration (7 days)" className="w-full p-3 border rounded-xl" />
                  <input name="doc" placeholder="Prescribed By" className="w-full p-3 border rounded-xl" />
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="doc" placeholder="Doctor's Name" className="w-full p-3 border rounded-xl outline-none" />
                    <input required type="date" name="date" className="w-full p-3 border rounded-xl outline-none" />
                  </div>
                  <textarea required name="note" placeholder="Observations, symptoms, plan..." className="w-full p-3 border rounded-xl h-32 outline-none focus:ring-2 focus:ring-indigo-500"></textarea>
                </>
              )}
              <div className="flex gap-2 pt-2">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-3 bg-slate-100 font-bold rounded-xl text-slate-500 hover:bg-slate-200 transition-all">Cancel</button>
                <button type="submit" className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 transition-all">Save To Vault</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100 no-print animate-in zoom-in duration-500">
          <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2 custom-scrollbar">
             <div className="p-5 bg-indigo-600 border border-indigo-700 rounded-3xl text-sm relative overflow-hidden text-white shadow-lg">
                <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                <p className="font-bold mb-1 flex items-center"><span className="mr-2">{ICONS.AI}</span> August AI Assistant</p>
                <p className="text-xs opacity-80 leading-relaxed italic">I have processed your Health ID memory. I can help analyze medicine interactions, lifestyle steps, or summarize your history.</p>
             </div>
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-50 border border-slate-200 text-slate-800'}`}>
                    {m.content}
                  </div>
               </div>
             ))}
             {isAiLoading && <div className="text-xs text-slate-400 font-bold px-4 animate-pulse flex items-center"><i className="fas fa-circle-notch fa-spin mr-2"></i> August is thinking...</div>}
          </div>
          <div className="flex gap-3 border-t border-slate-100 pt-4">
            <input value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} placeholder="Ask August about medicine interactions or history summary..." className="flex-grow p-4 bg-slate-100 rounded-2xl outline-none text-sm focus:ring-2 focus:ring-indigo-500 transition-all" />
            <button onClick={askAugustAI} disabled={isAiLoading || !userQuery.trim()} className="px-6 bg-indigo-600 text-white font-bold rounded-2xl disabled:opacity-50 transition-all hover:bg-indigo-700 shadow-lg flex items-center gap-2">
              <i className="fas fa-paper-plane"></i> <span className="hidden md:inline">Analyze</span>
            </button>
          </div>
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-6 no-print animate-in fade-in duration-500">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
             <h3 className="text-xl font-bold mb-4 text-slate-800 flex items-center">
               <span className="mr-2 text-indigo-600">{ICONS.SEARCH}</span> Universal HID Lookup
             </h3>
             <p className="text-slate-500 text-sm mb-6 leading-relaxed">Instantly retrieve medical history from any local Health ID in the vault. Perfect for doctors to review previous treatments.</p>
             <div className="flex flex-col md:flex-row gap-4">
                <input value={searchId} onChange={(e) => setSearchId(e.target.value)} className="flex-grow p-4 border border-slate-200 rounded-2xl font-mono tracking-widest outline-none focus:ring-2 focus:ring-indigo-500 transition-all uppercase" placeholder="HID-XXXX-XXXX" />
                <button onClick={handleSearch} className="px-8 py-4 bg-slate-800 text-white font-bold rounded-2xl transition-all hover:bg-black shadow-lg transform active:scale-95">Fetch Records</button>
             </div>
          </div>
          {searchResults && (
            <div className="bg-white rounded-3xl shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500 border border-slate-100">
              <div className="bg-slate-900 p-8 text-white flex justify-between items-center relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
                <div className="relative z-10">
                  <h4 className="text-2xl font-bold mb-1">{searchResults.profile?.name}</h4>
                  <p className="text-sm opacity-60 font-mono tracking-widest uppercase">{searchResults.profile?.healthId}</p>
                </div>
                <div className="text-right relative z-10">
                  <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-400">Patient Details</p>
                  <p className="text-lg font-bold">Blood Group: {searchResults.profile?.bloodGroup}</p>
                  <p className="text-sm opacity-60">Age: {searchResults.profile?.age}</p>
                </div>
              </div>
              <div className="p-8 grid md:grid-cols-2 gap-8 bg-white">
                <div className="space-y-6">
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center">
                      <i className="fas fa-pills mr-2 text-indigo-500"></i> Clinical Medications
                    </h5>
                    {(searchResults.medications || []).length > 0 ? searchResults.medications.map(m => (
                      <div key={m.id} className="p-4 bg-slate-50 rounded-2xl font-bold text-sm border mb-3 flex justify-between">
                        <span>{m.name}</span>
                        <span className="text-indigo-600">{m.dosage}</span>
                      </div>
                    )) : <p className="text-xs text-slate-400 italic">No medication history.</p>}
                  </div>
                </div>
                <div className="space-y-6">
                  <div>
                    <h5 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 flex items-center">
                      <i className="fas fa-phone mr-2 text-rose-500"></i> Emergency SOS
                    </h5>
                    <div className="p-5 bg-indigo-50 border border-indigo-100 rounded-3xl">
                      <p className="font-bold text-indigo-900 text-lg mb-1">{searchResults.profile?.emergencyContact?.name}</p>
                      <p className="text-sm font-bold text-indigo-600 tracking-wider"><i className="fas fa-phone-alt mr-2"></i>{searchResults.profile?.emergencyContact?.phone}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* PRINT VIEW */}
      {currentUser && (
        <div className="hidden print-only print-container bg-white text-black">
          <div className="border-b-4 border-slate-900 pb-8 mb-8 flex justify-between items-end">
            <div>
              <h1 className="text-4xl font-bold text-slate-900 uppercase tracking-tight mb-2">HealthShield Clinical Export</h1>
              <p className="text-slate-500 font-bold tracking-widest font-mono text-xl">{currentUser.profile?.healthId}</p>
            </div>
            <p className="text-xs font-bold text-slate-400 uppercase text-right">Generated: {new Date().toLocaleDateString()}</p>
          </div>
          <div className="grid grid-cols-2 gap-8 mb-12">
            <div className="p-8 bg-slate-50 border rounded-3xl">
              <h2 className="text-xs font-bold text-indigo-600 uppercase mb-4 tracking-widest">Patient Profile</h2>
              <div className="space-y-3 text-sm">
                <p><span className="text-slate-400 font-medium">Name:</span> <span className="font-bold">{currentUser.profile?.name}</span></p>
                <p><span className="text-slate-400 font-medium">DOB:</span> <span className="font-bold">{currentUser.profile?.dob}</span></p>
                <p><span className="text-slate-400 font-medium">Blood:</span> <span className="font-bold">{currentUser.profile?.bloodGroup}</span></p>
                <p><span className="text-slate-400 font-medium">SOS:</span> <span className="font-bold">{currentUser.profile?.emergencyContact?.name} ({currentUser.profile?.emergencyContact?.phone})</span></p>
              </div>
            </div>
          </div>
          <div className="space-y-12">
            <section><h3 className="text-xl font-bold border-b-2 border-slate-100 pb-3 mb-6 uppercase">Medical Conditions</h3>{(currentUser.problems || []).map(p => <div key={p.id} className="py-3 border-b border-slate-50 flex justify-between"><span className="font-bold text-lg">{p.condition}</span><span className="text-slate-500 font-medium">Onset: {p.onsetDate}</span></div>)}</section>
            <section><h3 className="text-xl font-bold border-b-2 border-slate-100 pb-3 mb-6 uppercase">Current Medications</h3>{(currentUser.medications || []).map(m => <div key={m.id} className="py-4 border-b border-slate-50"><p className="font-bold text-lg">{m.name} - {m.dosage}</p><p className="text-sm text-slate-500">{m.frequency} • {m.duration}</p></div>)}</section>
            <section><h3 className="text-xl font-bold border-b-2 border-slate-100 pb-3 mb-6 uppercase">Clinician Notes</h3>{(currentUser.notes || []).map(n => <div key={n.id} className="py-5 border-b border-slate-50"><p className="text-sm font-bold mb-2">DR. {(n.doctorName || '').toUpperCase()} • {n.date}</p><p className="text-base italic text-slate-700 leading-relaxed">"{n.note}"</p></div>)}</section>
          </div>
          <div className="mt-24 pt-10 border-t border-slate-100 text-[10px] text-slate-400 text-center uppercase tracking-[0.2em] italic">Official Medical Passport Secured by HealthShield Vault Architecture</div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allRecords, setAllRecords] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);
  const [copyFeedback, setCopyFeedback] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load records on initial mount
  useEffect(() => {
    const loadData = () => {
      const savedRecords = localStorage.getItem(STORAGE_KEY);
      const activeSession = localStorage.getItem(SESSION_KEY);
      if (savedRecords) {
        try {
          const loadedRecords = JSON.parse(savedRecords);
          setAllRecords(loadedRecords);
          if (activeSession) {
            const found = loadedRecords.find((r: HealthRecord) => r.profile?.healthId === activeSession);
            if (found) {
              setCurrentUser(found);
              setIsAuth(true);
            }
          }
        } catch (e) {
          console.error("Failed to parse local records", e);
        }
      }
    };
    loadData();
  }, []);

  const saveAllRecords = (records: HealthRecord[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    setAllRecords(records);
  };

  const handleRegister = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    const currentStored = localStorage.getItem(STORAGE_KEY);
    const existingRecords = currentStored ? JSON.parse(currentStored) : [];
    const updated = [...existingRecords, newRecord];

    saveAllRecords(updated);
    localStorage.setItem(LAST_HID_KEY, healthId);
    setShowRegSuccess(healthId);
  };

  const completeRegistration = () => {
    if (!showRegSuccess) return;
    const currentStored = localStorage.getItem(STORAGE_KEY);
    const records: HealthRecord[] = currentStored ? JSON.parse(currentStored) : [];
    const found = records.find(r => r.profile?.healthId === showRegSuccess);
    if (found) {
      setCurrentUser(found);
      setAllRecords(records);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');

    const currentStored = localStorage.getItem(STORAGE_KEY);
    if (!currentStored) {
      setAuthError("No records found in this vault. Please register first.");
      return;
    }

    const records: HealthRecord[] = JSON.parse(currentStored);
    const inputId = (loginId || '').trim().toUpperCase();
    const found = records.find(r => (r.profile?.healthId || '').trim().toUpperCase() === inputId);

    if (found) {
      setCurrentUser(found);
      setAllRecords(records); 
      localStorage.setItem(SESSION_KEY, found.profile.healthId);
      setIsAuth(true);
    } else {
      setAuthError("Health ID not found. Ensure you copied the full ID correctly.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopyFeedback(true);
    setTimeout(() => setCopyFeedback(false), 2000);
  };

  const addMedicalItem = (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    // Always use latest from storage to prevent data loss
    const currentStored = localStorage.getItem(STORAGE_KEY);
    const records: HealthRecord[] = currentStored ? JSON.parse(currentStored) : [];

    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };

    const updatedAll = records.map(r => r.profile?.healthId === currentUser.profile.healthId ? updatedUser : r);

    setCurrentUser(updatedUser);
    saveAllRecords(updatedAll);
    setShowAddModal(null);
  };

  const removeMedicalItem = (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Are you sure you want to remove this medical record?")) return;

    const currentStored = localStorage.getItem(STORAGE_KEY);
    const records: HealthRecord[] = currentStored ? JSON.parse(currentStored) : [];

    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };

    const updatedAll = records.map(r => r.profile?.healthId === currentUser.profile.healthId ? updatedUser : r);

    setCurrentUser(updatedUser);
    saveAllRecords(updatedAll);
  };

  const handleExportJSON = () => {
    if (!currentUser) return;
    const dataStr = JSON.stringify(currentUser, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `HealthShield_${currentUser.profile.healthId}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const importedRecord = JSON.parse(event.target?.result as string) as HealthRecord;
        if (!importedRecord.profile?.healthId) throw new Error("Invalid Format");
        const existingRecords = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
        const existingIndex = existingRecords.findIndex((r: HealthRecord) => r.profile?.healthId === importedRecord.profile.healthId);
        let updatedAll = [...existingRecords];
        if (existingIndex > -1) {
          if (confirm("ID exists. Overwrite?")) updatedAll[existingIndex] = importedRecord;
          else return;
        } else {
          updatedAll.push(importedRecord);
        }
        saveAllRecords(updatedAll);
        setCurrentUser(importedRecord);
        localStorage.setItem(SESSION_KEY, importedRecord.profile.healthId);
        setIsAuth(true);
        alert("Imported!");
      } catch (err) {
        alert("Import failed.");
      }
    };
    reader.readAsText(file);
  };

  const handleExportPDF = () => {
    window.print();
  };

  const completionScore = (() => {
    if (!currentUser) return 0;
    const metrics = [
      (currentUser.problems || []).length > 0,
      (currentUser.medications || []).length > 0,
      (currentUser.surgeries || []).length > 0,
      (currentUser.allergies || []).length > 0,
      (currentUser.notes || []).length > 0,
      !!currentUser.profile?.bloodGroup,
      !!currentUser.profile?.emergencyContact?.name
    ];
    return Math.round((metrics.filter(Boolean).length / metrics.length) * 100);
  })();

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = () => {
    const inputId = (searchId || '').trim().toUpperCase();
    const found = allRecords.find(r => (r.profile?.healthId || '').trim().toUpperCase() === inputId);
    setSearchResults(found || null);
  };

  if (!isAuth) {
    return (
