            <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16"></div>
            <div className="flex items-center space-x-6 relative z-10">
              <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner text-white">
                <i className="fas fa-database"></i>
              </div>
              <div>
                <h3 className="font-bold text-xl mb-1">Medical Records Vault</h3>
                <p className="text-xs text-slate-400 max-w-sm">Manage your health data securely. All changes are saved instantly to your device's vault.</p>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto relative z-10">
              <button onClick={handleExportJSON} className="flex-1 md:flex-none px-6 py-4 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-xs transition-all border border-white/10 flex items-center justify-center gap-2">
                <i className="fas fa-download"></i> Backup JSON
              </button>
              <button onClick={handleExportPDF} className="flex-1 md:flex-none px-6 py-4 bg-indigo-600 text-white hover:bg-indigo-700 rounded-xl font-bold text-xs transition-all shadow-lg flex items-center justify-center gap-2">
                <i className="fas fa-print"></i> Print Records
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <RecordCard title="Medical Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
              <div className="space-y-3">
                {(currentUser?.problems || []).map(p => (
                  <div key={p.id} className="p-4 bg-slate-50 rounded-2xl flex justify-between items-center border border-slate-100 group transition-all hover:bg-white hover:shadow-sm">
                    <div>
                      <span className="font-bold text-slate-800">{p.condition}</span>
                      <p className="text-[10px] text-slate-400 uppercase font-bold mt-1">
                        Onset: {p.onsetDate} • Status: {p.status}
                      </p>
                    </div>
                    <div className="flex items-center space-x-3">
                      <span className={`px-2 py-1 rounded text-[10px] font-bold ${p.severity === 'severe' ? 'bg-red-50 text-red-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        {p.severity.toUpperCase()}
                      </span>
                      <button onClick={() => removeMedicalItem('problems', p.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2">
                        <i className="fas fa-trash-alt"></i>
                      </button>
                    </div>
                  </div>
                ))}
                {(!currentUser?.problems || currentUser.problems.length === 0) && (
                  <div className="text-center py-10 border-2 border-dashed border-slate-100 rounded-3xl">
                    <p className="text-xs text-slate-400">No medical conditions recorded. Use "+ ADD NEW" to start.</p>
                  </div>
                )}
              </div>
            </RecordCard>

            <RecordCard title="Active Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
              <div className="space-y-3">
                {(currentUser?.medications || []).map(m => (
                  <div key={m.id} className="p-4 bg-slate-50 rounded-2xl flex justify-between items-center border border-slate-100 group transition-all hover:bg-white">
                    <div>
                      <span className="font-bold text-slate-800">{m.name}</span>
                      <p className="text-[10px] text-indigo-600 font-bold mt-1">{m.dosage} • {m.frequency}</p>
                    </div>
                    <div className="flex items-center space-x-2">
                      <span className="text-[10px] text-slate-400 font-mono">{m.duration}</span>
                      <button onClick={() => removeMedicalItem('medications', m.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2">
                        <i className="fas fa-trash-alt"></i>
                      </button>
                    </div>
                  </div>
                ))}
                {(!currentUser?.medications || currentUser.medications.length === 0) && (
                  <div className="text-center py-10 border-2 border-dashed border-slate-100 rounded-3xl">
                    <p className="text-xs text-slate-400">No active medications in vault.</p>
                  </div>
                )}
              </div>
            </RecordCard>

            <RecordCard title="Surgeries & Procedures" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
              <div className="space-y-3">
                {(currentUser?.surgeries || []).map(s => (
                  <div key={s.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center group transition-all hover:bg-white">
                    <div>
                      <p className="font-bold text-slate-800">{s.type}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{s.date} • {s.hospital}</p>
                    </div>
                    <button onClick={() => removeMedicalItem('surgeries', s.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2">
                      <i className="fas fa-trash-alt"></i>
                    </button>
                  </div>
                ))}
              </div>
            </RecordCard>

            <RecordCard title="Allergies" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
              <div className="flex flex-wrap gap-2">
                {(currentUser?.allergies || []).map(a => (
                  <div key={a.id} className="px-4 py-2 bg-rose-50 border border-rose-100 rounded-2xl text-xs font-bold text-rose-700 flex items-center space-x-3">
                    <span>{a.substance} ({a.severity.toUpperCase()})</span>
                    <button onClick={() => removeMedicalItem('allergies', a.id)} className="text-rose-300 hover:text-rose-700 transition-colors">
                      <i className="fas fa-times"></i>
                    </button>
                  </div>
                ))}
                {(!currentUser?.allergies || currentUser.allergies.length === 0) && <p className="text-xs text-slate-400 italic">No allergies recorded.</p>}
              </div>
            </RecordCard>

            <RecordCard title="Clinical Notes & History" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(currentUser?.notes || []).map(n => (
                  <div key={n.id} className="p-5 bg-indigo-50/30 rounded-3xl border border-indigo-100 relative group transition-all hover:bg-white">
                    <button onClick={() => removeMedicalItem('notes', n.id)} className="absolute top-4 right-4 text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all">
                      <i className="fas fa-trash-alt text-xs"></i>
                    </button>
                    <div className="flex items-center justify-between mb-3">
                      <p className="text-xs font-bold text-indigo-900 uppercase">Dr. {n.doctorName}</p>
                      <p className="text-[10px] text-slate-400 font-bold">{n.date}</p>
                    </div>
                    <p className="text-sm italic text-slate-600 leading-relaxed">"{n.note}"</p>
                  </div>
                ))}
              </div>
            </RecordCard>
          </div>
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600 transition-colors"><i className="fas fa-times text-xl"></i></button>
            <h3 className="text-xl font-bold mb-6 text-slate-800">Add {showAddModal.charAt(0).toUpperCase() + showAddModal.slice(1)} Record</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
              if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency'), prescribedBy: f.get('doc') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-3">
                    <select name="severity" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select>
                    <select name="status" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none"><option value="present">Present</option><option value="past">Past</option></select>
                  </div>
                  <input required type="date" name="onsetDate" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
                </>
              )}
              {showAddModal === 'med' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-3">
                    <input required name="dosage" placeholder="Dosage (500mg)" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                    <input required name="frequency" placeholder="Freq (1-0-1)" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                  </div>
                  <input name="duration" placeholder="Duration (e.g., 2 weeks)" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <div className="grid grid-cols-2 gap-3">
                    <input required name="doc" placeholder="Doctor's Name" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                    <input required type="date" name="date" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                  </div>
                  <textarea required name="note" placeholder="Treatment notes, consultation summary..." className="w-full p-4 bg-slate-50 border-none rounded-2xl h-40 outline-none focus:ring-2 focus:ring-indigo-500"></textarea>
                </>
              )}
              {showAddModal === 'surgery' && (
                <>
                  <input required name="type" placeholder="Procedure Type" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                  <input required type="date" name="date" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                  <input required name="hospital" placeholder="Hospital/Clinic Name" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Allergen (e.g., Peanuts)" className="w-full p-4 bg-slate-50 border-none rounded-2xl" />
                  <select name="severity" className="w-full p-4 bg-slate-50 border-none rounded-2xl"><option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option></select>
                </>
              )}
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 font-bold rounded-2xl text-slate-500 hover:bg-slate-200 transition-all">Cancel</button>
                <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-xl hover:bg-indigo-700 transition-all">Commit to Vault</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100 no-print animate-in zoom-in duration-500">
