                        <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                        <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500">
                          {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                      <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="XXXX XXXX XXXX" />
                    </div>
                    <div className="p-4 bg-indigo-50/50 rounded-2xl space-y-3 border border-indigo-100">
                      <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                      <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white outline-none" placeholder="Contact Name" />
                      <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white outline-none" placeholder="Contact Phone" />
                    </div>
                    <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition-all transform active:scale-[0.98]">Store in Vault</button>
                  </form>
                ) : (
                  <form onSubmit={handleLogin} className="space-y-6 animate-in fade-in duration-300">
                    <div>
                      <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Enter Your Secure Health ID</label>
                      <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono tracking-widest outline-none focus:ring-2 focus:ring-indigo-500 transition-all uppercase" placeholder="HID-XXXX-XXXX" />
                      {localStorage.getItem(LAST_HID_KEY) && (
                        <button type="button" onClick={() => setLoginId(localStorage.getItem(LAST_HID_KEY) || '')} className="mt-2 text-[10px] font-bold text-indigo-500 hover:text-indigo-700 uppercase tracking-tighter">
                          Use Last Created: {localStorage.getItem(LAST_HID_KEY)}
                        </button>
                      )}
                    </div>
                    <button type="submit" disabled={isLoading} className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl hover:bg-black transition-all shadow-lg transform active:scale-[0.98] disabled:opacity-50">
                      {isLoading ? 'Querying Database...' : 'Unlock Vault'}
                    </button>
                  </form>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout}>
      <div className="mb-4 no-print">
        <div className="inline-flex items-center gap-2 px-3 py-1 bg-indigo-100 text-indigo-700 rounded-full text-[10px] font-bold uppercase">
          <i className="fas fa-database animate-pulse"></i> IndexedDB Engine Connected
        </div>
      </div>

      {activeTab === 'dashboard' && (
        <div className="space-y-6 animate-in fade-in duration-500">
          {/* Dashboard Content - Unchanged but now reactive to async DB */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32"></div>
              <div className="relative z-10">
                <p className="text-indigo-200 text-[10px] font-bold uppercase mb-4 tracking-widest">Digital Health Passport</p>
                <div className="flex items-end justify-between">
                  <div>
                    <h1 className="text-4xl font-mono font-bold tracking-tighter mb-1">{currentUser?.profile?.healthId}</h1>
                    <button onClick={() => currentUser && copyToClipboard(currentUser.profile.healthId)} className="text-[10px] font-bold text-indigo-300 hover:text-white uppercase tracking-widest flex items-center">
                      <i className="fas fa-copy mr-1"></i> {copyFeedback ? 'Copied' : 'Copy ID'}
                    </button>
                  </div>
                  <div className="bg-white/10 px-4 py-2 rounded-xl backdrop-blur-md border border-white/10 text-center">
                    <p className="text-[8px] font-bold opacity-60 uppercase">Blood Type</p>
                    <p className="text-xl font-bold">{currentUser?.profile?.bloodGroup || 'N/A'}</p>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between">
                  <div>
                    <p className="text-[10px] text-indigo-300 uppercase font-bold tracking-tighter mb-1">Emergency SOS</p>
                    <p className="font-bold text-sm">{currentUser?.profile?.emergencyContact?.name} • {currentUser?.profile?.emergencyContact?.phone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] text-indigo-300 uppercase font-bold tracking-tighter mb-1">Identification</p>
                    <p className="font-bold text-sm">Age {currentUser?.profile?.age} • DOB {currentUser?.profile?.dob}</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <h3 className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-4">Vault Completion</h3>
              <div className="relative w-32 h-32 flex items-center justify-center mb-4">
                 <svg className="w-full h-full transform -rotate-90">
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-100" />
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={364.4} strokeDashoffset={364.4 - (364.4 * completionScore) / 100} strokeLinecap="round" className="text-indigo-600 transition-all duration-700" />
                 </svg>
                 <span className="absolute text-2xl font-black text-slate-800">{completionScore}%</span>
              </div>
              <p className="text-[10px] font-bold text-slate-400 leading-relaxed uppercase tracking-tighter">
                Record Status
              </p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.ALLERGY}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Allergies</p><p className="text-xl font-black text-slate-800">{(currentUser?.allergies || []).length}</p></div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.MEDS}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Active Meds</p><p className="text-xl font-black text-slate-800">{(currentUser?.medications || []).length}</p></div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.SURGERY}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Procedures</p><p className="text-xl font-black text-slate-800">{(currentUser?.surgeries || []).length}</p></div>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-4">
               <div className="w-12 h-12 bg-amber-50 text-amber-600 rounded-2xl flex items-center justify-center text-xl">{ICONS.NOTE}</div>
               <div><p className="text-[10px] font-bold text-slate-400 uppercase">Notes</p><p className="text-xl font-black text-slate-800">{(currentUser?.notes || []).length}</p></div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'records' && (
        <div className="space-y-6 pb-20 no-print animate-in slide-in-from-right-4 duration-500">
          <div className="bg-slate-900 rounded-3xl p-8 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16"></div>
            <div className="flex items-center space-x-6 relative z-10">
              <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-3xl shadow-inner text-white">
                <i className="fas fa-database"></i>
              </div>
              <div>
                <h3 className="font-bold text-xl mb-1">Database Records</h3>
                <p className="text-xs text-slate-400 max-w-sm">Manage your health data stored in the local IndexedDB vault.</p>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto relative z-10">
              <button onClick={handleExportJSON} className="flex-1 md:flex-none px-6 py-4 bg-white/10 hover:bg-white/20 rounded-xl font-bold text-xs transition-all border border-white/10 flex items-center justify-center gap-2">
                <i className="fas fa-download"></i> Backup JSON
              </button>
              <button onClick={handleExportPDF} className="flex-1 md:flex-none px-6 py-4 bg-indigo-600 text-white hover:bg-indigo-700 rounded-xl font-bold text-xs transition-all shadow-lg flex items-center justify-center gap-2">
                <i className="fas fa-print"></i> Print Records
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <RecordCard title="Medical Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
              <div className="space-y-3">
                {(currentUser?.problems || []).map(p => (
                  <div key={p.id} className="p-4 bg-slate-50 rounded-2xl flex justify-between items-center border border-slate-100">
                    <div>
                      <span className="font-bold text-slate-800">{p.condition}</span>
                      <p className="text-[10px] text-slate-400 uppercase font-bold mt-1">Onset: {p.onsetDate}</p>
                    </div>
                    <button onClick={() => removeMedicalItem('problems', p.id)} className="text-slate-300 hover:text-red-500 p-2"><i className="fas fa-trash-alt"></i></button>
                  </div>
                ))}
              </div>
            </RecordCard>
            <RecordCard title="Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('med')}>
              <div className="space-y-3">
                {(currentUser?.medications || []).map(m => (
                  <div key={m.id} className="p-4 bg-slate-50 rounded-2xl flex justify-between items-center border border-slate-100">
                    <div><span className="font-bold text-slate-800">{m.name}</span><p className="text-[10px] text-indigo-600 font-bold">{m.dosage}</p></div>
                    <button onClick={() => removeMedicalItem('medications', m.id)} className="text-slate-300 hover:text-red-500 p-2"><i className="fas fa-trash-alt"></i></button>
                  </div>
                ))}
              </div>
            </RecordCard>
          </div>
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600"><i className="fas fa-times text-xl"></i></button>
            <h3 className="text-xl font-bold mb-6">Add {showAddModal}</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
              if (showAddModal === 'med') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), duration: f.get('duration'), frequency: f.get('frequency') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition" className="w-full p-4 bg-slate-50 rounded-2xl" />
                  <input required type="date" name="onsetDate" className="w-full p-4 bg-slate-50 rounded-2xl" />
                  <select name="severity" className="w-full p-4 bg-slate-50 rounded-2xl"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select>
                  <select name="status" className="w-full p-4 bg-slate-50 rounded-2xl"><option value="present">Present</option><option value="past">Past</option></select>
                </>
              )}
              {showAddModal === 'med' && (
                <>
                  <input required name="name" placeholder="Medicine Name" className="w-full p-4 bg-slate-50 rounded-2xl" />
                  <input required name="dosage" placeholder="Dosage" className="w-full p-4 bg-slate-50 rounded-2xl" />
                  <input name="duration" placeholder="Duration" className="w-full p-4 bg-slate-50 rounded-2xl" />
                  <input name="frequency" placeholder="Frequency" className="w-full p-4 bg-slate-50 rounded-2xl" />
                </>
              )}
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 font-bold rounded-2xl">Cancel</button>
                <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-xl">Commit</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeTab === 'august' && (
        <div className="flex flex-col h-[calc(100vh-14rem)] bg-white rounded-3xl p-6 shadow-sm border border-slate-100 no-print animate-in zoom-in duration-500">
          <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2 custom-scrollbar">
             <div className="p-6 bg-gradient-to-br from-indigo-600 to-indigo-800 border-none rounded-3xl text-sm relative overflow-hidden text-white shadow-xl">
                <p className="font-bold mb-1 flex items-center text-lg"><span className="mr-2">{ICONS.AI}</span> August AI Assistant</p>
                <p className="text-xs opacity-80 leading-relaxed italic">Analyzing your Database Records...</p>
             </div>
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-5 rounded-3xl text-sm ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-50 border border-slate-100 text-slate-800'}`}>
                    {m.content}
                  </div>
               </div>
             ))}
             {isAiLoading && <div className="text-xs text-slate-400 font-bold px-4 animate-pulse flex items-center"><i className="fas fa-circle-notch fa-spin mr-2"></i> August is querying your history...</div>}
          </div>
          <div className="flex gap-3 border-t border-slate-100 pt-4">
            <input value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} placeholder="Ask August about interactions..." className="flex-grow p-4 bg-slate-50 rounded-2xl outline-none" />
            <button onClick={askAugustAI} disabled={isAiLoading || !userQuery.trim()} className="px-8 bg-indigo-600 text-white font-bold rounded-2xl">Analyze</button>
          </div>
        </div>
      )}

      {activeTab === 'history' && (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-10 rounded-3xl shadow-sm border border-slate-100">
             <h3 className="text-2xl font-bold mb-4 text-slate-800 flex items-center">
               <span className="mr-2 text-indigo-600">{ICONS.SEARCH}</span> Search IndexedDB Vault
             </h3>
             <p className="text-slate-500 text-sm mb-8">Access any medical identity stored in this browser's local database.</p>
             <div className="flex flex-col md:flex-row gap-4">
                <input value={searchId} onChange={(e) => setSearchId(e.target.value)} className="flex-grow p-5 bg-slate-50 rounded-2xl font-mono text-lg uppercase" placeholder="HID-XXXX-XXXX" />
                <button onClick={handleSearch} className="px-10 py-5 bg-slate-800 text-white font-bold rounded-2xl">Search Database</button>
             </div>
          </div>
          {searchResults && (
            <div className="bg-white rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 border border-slate-100">
              <div className="bg-slate-900 p-8 text-white">
                <h4 className="text-2xl font-bold">{searchResults.profile?.name}</h4>
                <p className="text-sm opacity-60 font-mono uppercase">{searchResults.profile?.healthId}</p>
              </div>
              <div className="p-8">
                 <p className="font-bold text-slate-800">Records found: {(searchResults.problems || []).length} conditions, {(searchResults.medications || []).length} meds.</p>
              </div>
            </div>
          )}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);
  const [copyFeedback, setCopyFeedback] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize DB and Session
  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();

        // Migration logic: Move localStorage data to IndexedDB if it exists
        const oldData = localStorage.getItem(STORAGE_KEY);
        if (oldData) {
          const records: HealthRecord[] = JSON.parse(oldData);
          for (const rec of records) {
            await dbService.saveRecord(rec);
          }
          localStorage.removeItem(STORAGE_KEY); // Clean up
        }

        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setIsLoading(false);
      }
    };
    bootstrap();
  }, []);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database. Check browser permissions.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const inputId = (loginId || '').trim().toUpperCase();

    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found in the local database. Ensure the ID is exactly correct.");
      }
    } catch (err) {
      setAuthError("Database query error.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopyFeedback(true);
    setTimeout(() => setCopyFeedback(false), 2000);
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;

    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };

    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowAddModal(null);
    } catch (err) {
      alert("Error saving medical update.");
    }
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Are you sure you want to remove this medical record?")) return;

    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };

    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      alert("Error removing medical record.");
    }
  };

  const handleExportJSON = () => {
    if (!currentUser) return;
    const dataStr = JSON.stringify(currentUser, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `HealthShield_${currentUser.profile.healthId}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportJSON = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const importedRecord = JSON.parse(event.target?.result as string) as HealthRecord;
        if (!importedRecord.profile?.healthId) throw new Error("Invalid Format");

        await dbService.saveRecord(importedRecord);
        setCurrentUser(importedRecord);
        localStorage.setItem(SESSION_KEY, importedRecord.profile.healthId);
        setIsAuth(true);
        alert("Record imported and saved to database!");
      } catch (err) {
        alert("Import failed.");
      }
    };
    reader.readAsText(file);
  };

  const handleExportPDF = () => {
    window.print();
  };

  const completionScore = (() => {
    if (!currentUser) return 0;
    const metrics = [
      (currentUser.problems || []).length > 0,
      (currentUser.medications || []).length > 0,
      (currentUser.surgeries || []).length > 0,
      (currentUser.allergies || []).length > 0,
      (currentUser.notes || []).length > 0,
      !!currentUser.profile?.bloodGroup,
      !!currentUser.profile?.emergencyContact?.name
    ];
    return Math.round((metrics.filter(Boolean).length / metrics.length) * 100);
  })();

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = async () => {
    setIsLoading(true);
    const inputId = (searchId || '').trim().toUpperCase();
    const found = await dbService.getRecord(inputId);
    setSearchResults(found);
    setIsLoading(false);
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Accessing Secure Vault Database...</p>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100 min-h-[600px]">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4 tracking-tight">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8 leading-relaxed">Secure medical storage with instant AI insights. Access your clinical history anywhere with your unique ID.</p>
              <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-200 mb-2">Vault Technology</p>
                <p className="text-sm">Records are stored in a structured IndexedDB within your browser, providing high-performance and reliable medical history management.</p>
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center bg-slate-50/30">
            {showRegSuccess ? (
              <div className="animate-in fade-in slide-in-from-right-4 duration-500 text-center">
                <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-3xl mx-auto mb-6 shadow-sm">
                  <i className="fas fa-check-circle"></i>
                </div>
                <h3 className="text-2xl font-bold text-slate-800 mb-2">Database Updated!</h3>
                <p className="text-slate-500 text-sm mb-8 leading-relaxed">Your secure Health ID is now registered in the local vault. Copy this ID to log in on this browser anytime.</p>

                <div className="p-6 bg-white rounded-2xl border border-slate-100 flex flex-col items-center justify-center mb-8 shadow-sm">
                  <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest mb-2">Permanent Health ID</span>
                  <span className="font-mono font-bold text-slate-900 text-2xl tracking-widest">{showRegSuccess}</span>
                  <button onClick={() => copyToClipboard(showRegSuccess)} className={`mt-4 px-6 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${copyFeedback ? 'bg-emerald-500 text-white' : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100 border border-indigo-100'}`}>
                    <i className={`fas ${copyFeedback ? 'fa-check' : 'fa-copy'}`}></i>
                    {copyFeedback ? 'Copied to Clipboard' : 'Copy Health ID'}
                  </button>
                </div>

                <button onClick={completeRegistration} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg hover:bg-indigo-700 transition-all transform active:scale-[0.98] flex items-center justify-center gap-3">
                  Open My Records <i className="fas fa-arrow-right"></i>
                </button>
              </div>
            ) : (
              <>
                <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
                  <button onClick={() => {setAuthMode('register'); setAuthError('');}} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
                  <button onClick={() => {setAuthMode('login'); setAuthError('');}} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
                </div>

                {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold border border-red-100 animate-in shake duration-300">{authError}</div>}

                {authMode === 'register' ? (
                  <form onSubmit={handleRegister} className="space-y-4 max-h-[450px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-200 animate-in fade-in duration-300">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                        <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Patient Name" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                        <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                        <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                        <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500">
                          {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar (12 Digits)</label>
                      <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500" placeholder="XXXX XXXX XXXX" />
                    </div>
                    <div className="p-4 bg-indigo-50/50 rounded-2xl space-y-3 border border-indigo-100">
                      <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
