                  <input required name="condition" placeholder="Condition" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500" />
                  <div className="grid grid-cols-2 gap-3">
                    <input required type="date" name="onsetDate" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
