               <span className="mr-2 text-indigo-600">{ICONS.SEARCH}</span> Local Vault Lookup
             </h3>
             <p className="text-slate-500 text-sm mb-8">Access any medical identity stored in this browser's local database.</p>
             <div className="flex flex-col md:flex-row gap-4">
                <input value={searchId} onChange={(e) => setSearchId(e.target.value)} className="flex-grow p-5 bg-slate-50 rounded-2xl font-mono text-lg uppercase" placeholder="HID-XXXX-XXXX" />
                <button onClick={handleSearch} className="px-10 py-5 bg-slate-800 text-white font-bold rounded-2xl">Search Database</button>
             </div>
          </div>
          {searchResults && (
            <div className="bg-white rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 border border-slate-100">
              <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
                <div>
                  <h4 className="text-2xl font-bold">{searchResults.profile?.name}</h4>
                  <p className="text-sm opacity-60 font-mono uppercase">{searchResults.profile?.healthId}</p>
                </div>
                {searchResults.profile?.isPremium && <i className="fas fa-crown text-amber-400 text-3xl"></i>}
              </div>
              <div className="p-8">
                 <p className="font-bold text-slate-800">Records found: {(searchResults.problems || []).length} conditions, {(searchResults.medications || []).length} meds.</p>
              </div>
            </div>
          )}
        </div>
      ) : null}

      {/* Payment / Order Summary Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-md rounded-[2rem] p-8 shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
            <button onClick={() => setShowPaymentModal(false)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600"><i className="fas fa-times text-xl"></i></button>

            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-4">
                <i className="fas fa-shopping-cart"></i>
              </div>
              <h3 className="text-2xl font-bold text-slate-900">Order Summary</h3>
              <p className="text-slate-500 text-sm">Review your subscription details</p>
            </div>

            <div className="space-y-4 mb-8">
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-slate-500 font-medium">Plan Item</span>
                  <span className="font-bold text-slate-900">HealthShield Premium</span>
                </div>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-slate-500 font-medium">Duration</span>
                  <span className="font-bold text-slate-900">1 Month</span>
                </div>
                <div className="flex justify-between items-center mb-2 pt-2 border-t border-slate-200">
                  <span className="text-slate-500 font-medium">Subtotal</span>
                  <span className="font-bold text-slate-900">₹{MONTHLY_PRICE}.00</span>
                </div>
                <div className="flex justify-between items-center mb-2 text-emerald-600">
                  <span className="font-medium">Taxes & Fees</span>
                  <span className="font-bold">₹0.00</span>
                </div>
              </div>

              <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                <span className="text-indigo-900 font-bold text-lg">Amount to Pay</span>
                <span className="text-indigo-900 font-black text-2xl">₹{MONTHLY_PRICE}.00</span>
              </div>
            </div>

            <div className="space-y-3">
              <button 
                onClick={triggerGPay}
                className="w-full bg-slate-900 text-white font-bold py-4 rounded-2xl shadow-xl flex items-center justify-center gap-3 hover:bg-black transition-all"
              >
                <i className="fab fa-google-pay text-3xl"></i> Pay with GPay
              </button>

              <div className="relative py-2 flex items-center">
                <div className="flex-grow border-t border-slate-100"></div>
                <span className="flex-shrink mx-4 text-slate-400 text-[10px] font-bold uppercase tracking-widest">Or simulate for demo</span>
                <div className="flex-grow border-t border-slate-100"></div>
              </div>

              <button 
                onClick={handleSubscribe}
                className="w-full bg-emerald-100 text-emerald-700 font-bold py-4 rounded-2xl border border-emerald-200 hover:bg-emerald-200 transition-all"
              >
                Confirm Simulation Payment
              </button>
            </div>

            <p className="text-[9px] text-center text-slate-400 mt-6 px-4">
              Payment secure via UPI intent. Processing for ID: <span className="font-mono text-indigo-500 font-bold">{PREMIUM_VPA}</span>
            </p>
          </div>
        </div>
      )}

      {/* Generic Add Modal - Keeping existing functionality */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-slate-600"><i className="fas fa-times text-xl"></i></button>
            <h3 className="text-xl font-bold mb-6 text-slate-800">Add {showAddModal} Record</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), status: f.get('status'), onsetDate: f.get('onsetDate'), severity: f.get('severity') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
                  <div className="grid grid-cols-2 gap-3">
                    <input required type="date" name="onsetDate" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
                    <select name="severity" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none"><option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option></select>
                  </div>
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <div className="grid grid-cols-2 gap-3">
                    <input required name="doc" placeholder="Doctor's Name" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
                    <input required type="date" name="date" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
                  </div>
                  <input name="clinic" placeholder="Clinic Name" className="w-full p-4 bg-slate-50 border-none rounded-2xl outline-none" />
                  <textarea required name="note" placeholder="Consultation notes..." className="w-full p-4 bg-slate-50 border-none rounded-2xl h-40 outline-none"></textarea>
                </>
              )}
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 font-bold rounded-2xl">Cancel</button>
                <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-xl">Commit</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';
const PREMIUM_VPA = "9787551548@okbizaxis";
const MONTHLY_PRICE = 99;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('register');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<'problem' | 'med' | 'surgery' | 'allergy' | 'note' | null>(null);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [copyFeedback, setCopyFeedback] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize DB and Session
  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const oldData = localStorage.getItem(STORAGE_KEY);
        if (oldData) {
          const records: HealthRecord[] = JSON.parse(oldData);
          for (const rec of records) {
            await dbService.saveRecord(rec);
          }
          localStorage.removeItem(STORAGE_KEY);
        }

        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setIsLoading(false);
      }
    };
    bootstrap();
  }, []);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId,
      isPremium: false
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const inputId = (loginId || '').trim().toUpperCase();
    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found in the local vault.");
      }
    } catch (err) {
      setAuthError("Database error.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const handleSubscribe = async () => {
    if (!currentUser) return;
    setIsLoading(true);

    // Update premium status in DB
    const expiry = new Date();
    expiry.setMonth(expiry.getMonth() + 1);

    const updatedUser = {
      ...currentUser,
      profile: {
        ...currentUser.profile,
        isPremium: true,
        subscriptionExpiry: expiry.toISOString()
      }
    };

    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowPaymentModal(false);
      alert("Subscription confirmed! Your Premium Health Vault is now active.");
    } catch (err) {
      alert("Error processing subscription record.");
    } finally {
      setIsLoading(false);
    }
  };

  const triggerGPay = () => {
    // UPI Intent URL - opens GPay or other UPI apps on mobile
    const upiUrl = `upi://pay?pa=${PREMIUM_VPA}&pn=HealthShieldAI&am=${MONTHLY_PRICE}&cu=INR&tn=Monthly_Premium_Access`;
    window.location.href = upiUrl;

    // Note: Since we can't verify external UPI success in a web demo without a backend,
    // we provide a manual confirmation button to simulate the successful return.
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopyFeedback(true);
    setTimeout(() => setCopyFeedback(false), 2000);
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowAddModal(null);
    } catch (err) {
      alert("Error saving record.");
    }
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      alert("Error removing record.");
    }
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const handleSearch = async () => {
    setIsLoading(true);
    const inputId = (searchId || '').trim().toUpperCase();
    const found = await dbService.getRecord(inputId);
    setSearchResults(found);
    setIsLoading(false);
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Accessing Secure Vault...</p>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="max-w-5xl w-full grid grid-cols-1 md:grid-cols-2 bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-100 min-h-[600px]">
          <div className="bg-indigo-700 p-10 text-white flex flex-col justify-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20"></div>
            <div className="relative z-10">
              <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-indigo-700 text-3xl mb-8 shadow-xl">{ICONS.LOCK}</div>
              <h1 className="text-4xl font-bold mb-4 tracking-tight">HealthShield AI</h1>
              <p className="text-indigo-100 text-lg mb-8 leading-relaxed">Secure medical storage with instant AI insights. Access your clinical history anywhere with your unique ID.</p>
              <div className="p-4 bg-white/10 rounded-2xl border border-white/10">
                <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-200 mb-2">Vault Technology</p>
                <p className="text-sm">Structured IndexedDB records provide a permanent, reliable local health database.</p>
              </div>
            </div>
          </div>
          <div className="p-10 flex flex-col justify-center bg-slate-50/30">
            {showRegSuccess ? (
              <div className="animate-in fade-in slide-in-from-right-4 duration-500 text-center">
                <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-3xl mx-auto mb-6 shadow-sm">
                  <i className="fas fa-check-circle"></i>
                </div>
                <h3 className="text-2xl font-bold text-slate-800 mb-2">Registration Success!</h3>
                <p className="text-slate-500 text-sm mb-8 leading-relaxed">Save your Health ID to access your vault in the future.</p>

                <div className="p-6 bg-white rounded-2xl border border-slate-100 flex flex-col items-center justify-center mb-8 shadow-sm">
                  <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest mb-2">Your Identity Token</span>
                  <span className="font-mono font-bold text-slate-900 text-2xl tracking-widest">{showRegSuccess}</span>
                  <button onClick={() => copyToClipboard(showRegSuccess)} className={`mt-4 px-6 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${copyFeedback ? 'bg-emerald-500 text-white' : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100 border border-indigo-100'}`}>
                    <i className={`fas ${copyFeedback ? 'fa-check' : 'fa-copy'}`}></i>
                    {copyFeedback ? 'Copied' : 'Copy ID'}
                  </button>
                </div>

                <button onClick={completeRegistration} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg hover:bg-indigo-700 transition-all flex items-center justify-center gap-3">
                  Enter Vault <i className="fas fa-arrow-right"></i>
                </button>
              </div>
            ) : (
              <>
                <div className="bg-slate-100 p-1 rounded-xl flex mb-8">
                  <button onClick={() => {setAuthMode('register'); setAuthError('');}} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'register' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Register</button>
                  <button onClick={() => {setAuthMode('login'); setAuthError('');}} className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${authMode === 'login' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>Login</button>
                </div>
                {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-xl text-xs font-bold border border-red-100">{authError}</div>}
                {authMode === 'register' ? (
                  <form onSubmit={handleRegister} className="space-y-4 max-h-[450px] overflow-y-auto pr-2 animate-in fade-in duration-300">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Full Name</label>
                        <input required name="name" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="John Doe" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Age</label>
                        <input required name="age" type="number" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">DOB</label>
                        <input required name="dob" type="date" className="w-full px-4 py-2 rounded-xl border border-slate-200" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Blood Group</label>
                        <select name="bloodGroup" className="w-full px-4 py-2 rounded-xl border border-slate-200">
                          {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase">Aadhaar</label>
                      <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-2 rounded-xl border border-slate-200" placeholder="XXXX XXXX XXXX" />
                    </div>
                    <div className="p-4 bg-indigo-50/50 rounded-2xl space-y-3 border border-indigo-100">
                      <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency SOS</p>
                      <input required name="eName" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Name" />
                      <input required name="ePhone" className="w-full px-4 py-2 rounded-xl border border-slate-200 bg-white" placeholder="Contact Phone" />
                    </div>
                    <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700">Initialize Vault</button>
                  </form>
                ) : (
                  <form onSubmit={handleLogin} className="space-y-6 animate-in fade-in duration-300">
                    <div>
                      <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block">Secure Health ID</label>
                      <input required value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-4 py-4 rounded-xl border border-slate-200 text-lg font-mono tracking-widest uppercase" placeholder="HID-XXXX-XXXX" />
                    </div>
                    <button type="submit" disabled={isLoading} className="w-full bg-slate-800 text-white font-bold py-4 rounded-xl hover:bg-black shadow-lg">
                      {isLoading ? 'Decrypting Vault...' : 'Unlock Database'}
                    </button>
                  </form>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout} isPremium={currentUser?.profile?.isPremium}>
      {activeTab === 'subscription' ? (
        <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
          <div className="bg-gradient-to-br from-indigo-900 to-indigo-950 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden border border-indigo-800/50">
            <div className="absolute top-0 right-0 w-80 h-80 bg-white/5 rounded-full -mr-40 -mt-40"></div>
            <div className="absolute bottom-0 left-0 w-64 h-64 bg-amber-500/10 rounded-full -ml-32 -mb-32"></div>

            <div className="relative z-10 grid md:grid-cols-2 gap-10 items-center">
              <div>
                <div className="inline-flex items-center gap-2 px-3 py-1 bg-amber-500/20 text-amber-400 rounded-full text-[10px] font-bold uppercase tracking-widest mb-6 border border-amber-500/20">
                  <i className="fas fa-crown"></i> Premium Access
                </div>
                <h1 className="text-4xl font-bold mb-4">Upgrade to the Ultimate Medical Vault</h1>
                <p className="text-indigo-200 text-lg leading-relaxed mb-8">Unlock unlimited August AI clinical analysis, cloud backup simulation, and detailed procedure logs.</p>
